#define MAX_SLAYER_ATTR_SUM_OLD			330
#define MAX_SLAYER_DOMAIN_SUM_OLD		100
#define MAX_VAMPIRE_LEVEL_OLD			100

#define	MAX_SLAYER_ATTR					315
#define	MAX_SLAYER_ATTR_SUM				475
#define MAX_VAMPIRE_LEVEL				150


