//-----------------------------------------------------------------------------
// Skill box
//
// The skill box sits just left of the minimap, level with its top.
// C_VS_UI_SKILL draws it from SkillEtc*.spk.
//-----------------------------------------------------------------------------
static const int SKILL_BOX_SIZE = 42;	// C_VS_UI_SKILL's m_skill_guard_x/y
static const int SKILL_BOX_GAP = 1;		// the guard's edge is clear, so the tile reads ~4px off

static RECT s_skill_box = { 0, 0, 0, 0 };

void g_GetSkillBoxRect(RECT* rect)
{
	*rect = s_skill_box;
}

// The visible part of the simple information panel (its art is transparent
// above SIMPLE_PANEL_TOP). The level-up and resurrection buttons sit flush
// against its right edge.
static RECT s_simple_panel = { 0, 0, 0, 0 };

void g_GetSimplePanelRect(RECT* rect)
{
	*rect = s_simple_panel;
}

//-----------------------------------------------------------------------------
// C_VS_UI_TRIBE::PlaceSkillBox
//
// Beside the minimap's resting spot, so it stays put while the minimap is
// hidden or dragged.
//-----------------------------------------------------------------------------
void C_VS_UI_TRIBE::PlaceSkillBox(bool bl_force)
{
	RECT map;
	m_pC_minimap->GetRestingRect(&map);

	RECT box;
	box.left = map.left - SKILL_BOX_GAP - SKILL_BOX_SIZE;
	box.top = map.top;
	box.right = box.left + SKILL_BOX_SIZE;
	box.bottom = box.top + SKILL_BOX_SIZE;

	if (bl_force || memcmp(&box, &s_skill_box, sizeof(RECT)) != 0)
	{
		s_skill_box = box;
		m_pC_skill->SetStartPoint(box.left, box.top);
	}
}

// The panel's STR/DEX/INT columns, and their colours.
static const int SIMPLE_STAT_COLUMN_X[3] = { 20, 97, 178 };
static const COLORREF SIMPLE_STAT_RGB[3] = { RGB(255, 0, 0), RGB(0, 255, 0), RGB(0, 100, 255) };

// While a slayer's stats can still grow, each column ends in an EXP ring, and
// the columns close up to the left to make room for it.
static const int SIMPLE_STAT_RING_COLUMN_X[3] = { 14, 92, 170 };
static const int SIMPLE_STAT_RING_X = 50;		// the ring's left edge, from its column's
static const int SIMPLE_STAT_RING_TOP = -1;		// its top, from the stat row's
static const int SIMPLE_STAT_RING_D = 14;		// across

//-----------------------------------------------------------------------------
// Slayer stat EXP
//
// How the server grows a slayer's stats (Slayer::divideAttrExp): each has its
// own EXP toward its next point, up to the limits at MAX_SLAYER_ATTR_OLD. A
// stat at its limit takes no more EXP. Once the three total
// MAX_SLAYER_ATTR_SUM every point has been handed out, and a stat only rises
// by taking a point from another.
//-----------------------------------------------------------------------------
struct SLAYER_STAT_EXP
{
	int		cap;		// the most the stat can reach for now
	int		goal;		// EXP its next point takes; 0 once it is at its cap
	int		remain;		// how much of that is still to earn
};

static void g_GetSlayerStatExp(int stat, SLAYER_STAT_EXP& info)
{
	const int pure[3] = { g_char_slot_ingame.STR_PURE, g_char_slot_ingame.DEX_PURE, g_char_slot_ingame.INT_PURE };
	const int remain[3] = { g_char_slot_ingame.STR_EXP_REMAIN, g_char_slot_ingame.DEX_EXP_REMAIN, g_char_slot_ingame.INT_EXP_REMAIN };

	int domain_level_max = 0;

	for (int d = SKILLDOMAIN_BLADE; d <= SKILLDOMAIN_ENCHANT; d++)
		domain_level_max = max(domain_level_max, (*g_pSkillManager)[d].GetDomainLevel());

	const bool bl_bound = domain_level_max <= MAX_SLAYER_DOMAIN_SUM_OLD &&
		pure[0] + pure[1] + pure[2] <= MAX_SLAYER_ATTR_SUM_OLD;

	info.cap = bl_bound ? MAX_SLAYER_ATTR_OLD : MAX_SLAYER_ATTR;
	info.goal = 0;
	info.remain = 0;

	// This also keeps the lookup inside the EXP tables, which stop at
	// MAX_SLAYER_ATTR. A negative remainder is how older servers marked a
	// capped stat.
	if (pure[stat] < 1 || pure[stat] >= info.cap || remain[stat] < 0)
		return;

	const ExpInfo& exp = stat == 0 ? g_pExperienceTable->GetSTRInfo(pure[0])
		: stat == 1 ? g_pExperienceTable->GetDEXInfo(pure[1])
		: g_pExperienceTable->GetINTInfo(pure[2]);

	if (exp.GoalExp <= 0)
		return;

	info.goal = exp.GoalExp;
	info.remain = min(remain[stat], info.goal);
}

// The rings show while a slayer still has stat points to earn.
static bool g_IsSlayerStatRingShown()
{
	return g_eRaceInterface == RACE_SLAYER &&
		g_char_slot_ingame.STR_PURE + g_char_slot_ingame.DEX_PURE + g_char_slot_ingame.INT_PURE < MAX_SLAYER_ATTR_SUM;
}

// How far a slayer stat is toward its next point, in tenths of a percent. A
// stat at its cap is full, which is where the server leaves its EXP.
static int g_GetSlayerStatPermille(int stat)
{
	SLAYER_STAT_EXP info;
	g_GetSlayerStatExp(stat, info);

	if (info.goal <= 0)
		return 1000;

	return (int)((__int64)(info.goal - info.remain) * 1000 / info.goal);
}

// How much of a pixel at dist from a disc's centre the disc covers, 0 to 1.
static float g_DiscCoverage(float radius, float dist)
{
	const float cover = radius - dist + 0.5f;
	return cover < 0 ? 0 : (cover > 1 ? 1 : cover);
}

// From colour a to colour b by t (0 to 1), channel by channel, in the back
// surface's 16-bit format.
static WORD g_BlendPixel(WORD a, WORD b, float t)
{
	if (t <= 0)
		return a;

	if (t >= 1)
		return b;

	const bool bl_565 = CDirectDraw::Is565();
	const int mask[3] = { bl_565 ? 0xF800 : 0x7C00, bl_565 ? 0x07E0 : 0x03E0, 0x001F };
	const int k = (int)(t * 256);
	WORD out = 0;

	for (int i = 0; i < 3; i++)
	{
		const int ca = a & mask[i];
		const int cb = b & mask[i];
		out |= (WORD)((ca + (((cb - ca) * k) >> 8)) & mask[i]);
	}

	return out;
}

//-----------------------------------------------------------------------------
// g_DrawExpRing
//
// An EXP bar bent into a ring d pixels across, its top-left at (left, top):
// the track's light rim round its dark trough, and the fill laid clockwise
// from 12 o'clock as far as permille, its colours running round the ring as
// they run along the bar. The colours are read from the bar's own sprites,
// and the edges blend into what is under them. Needs the back surface locked.
//-----------------------------------------------------------------------------
static void g_DrawExpRing(C_SPRITE_PACK* p_spk, SPRITE_ID track, SPRITE_ID fill, int left, int top, int d, int permille)
{
	const CSprite& track_sprite = p_spk->GetSprite(track);
	const CSprite& fill_sprite = p_spk->GetSprite(fill);

	const WORD rim = track_sprite.GetPixel(1, 0);
	const WORD trough = track_sprite.GetPixel(1, 1);
	const int fill_w = fill_sprite.GetWidth();
	const int fill_row = fill_sprite.GetHeight() / 2;

	WORD* mem = (WORD*)gpC_base->m_p_DDSurface_back->GetSurfacePointer();
	const long pitch = gpC_base->m_p_DDSurface_back->GetSurfacePitch() / 2;

	// the trough is 2.5px wide, with a 1px rim either side of it
	const float outer = d / 2.0f;
	const float hole = outer - 4.5f;
	const float cx = left + outer;
	const float cy = top + outer;

	for (int py = max(0, top); py < min(top + d, g_pUserInformation->iResolution_y); py++)
	{
		for (int px = max(0, left); px < min(left + d, g_pUserInformation->iResolution_x); px++)
		{
			const float dx = px + 0.5f - cx;
			const float dy = py + 0.5f - cy;
			const float dist = sqrtf(dx * dx + dy * dy);
			const float cover = g_DiscCoverage(outer, dist) * (1 - g_DiscCoverage(hole, dist));

			if (cover <= 0)
				continue;

			// how far round from 12 o'clock, clockwise, 0 to 1
			float turn = atan2f(dx, -dy) / 6.2831853f;

			if (turn < 0)
				turn += 1;

			const WORD band = (turn * 1000 < permille)
				? fill_sprite.GetPixel(min(fill_w - 1, (int)(turn * fill_w)), fill_row)
				: trough;

			WORD color = g_BlendPixel(rim, band, g_DiscCoverage(outer - 1, dist));
			color = g_BlendPixel(color, rim, g_DiscCoverage(hole + 1, dist));

			WORD& dest = mem[py * pitch + px];
			dest = g_BlendPixel(dest, color, cover);
		}
	}
}

//-----------------------------------------------------------------------------
// g_DrawGlowField
//
// A soft halo of one colour hugging a shape, from a distance field: field
// holds, for each pixel of a w by h box whose top-left lands at (left, top),
// how far that pixel is from the shape in sixteenths of a pixel, or 255 for
// no halo. The halo is strongest against the shape and fades to nothing
// width pixels out; strength (0 to 1) is how solid it is at the edge. Needs
// the back surface locked.
//-----------------------------------------------------------------------------
static void g_DrawGlowField(const BYTE* field, int w, int h, int left, int top, WORD color, int width, float strength)
{
	WORD* mem = (WORD*)gpC_base->m_p_DDSurface_back->GetSurfacePointer();
	const long pitch = gpC_base->m_p_DDSurface_back->GetSurfacePitch() / 2;

	const int x0 = max(0, -left), y0 = max(0, -top);
	const int x1 = min(w, g_pUserInformation->iResolution_x - left);
	const int y1 = min(h, g_pUserInformation->iResolution_y - top);
	const float scale = 1.0f / (16 * width);

	for (int fy = y0; fy < y1; fy++)
	{
		const BYTE* row = field + fy * w;
		WORD* dest = mem + (top + fy) * pitch + left;

		for (int fx = x0; fx < x1; fx++)
		{
			if (row[fx] == 255)
				continue;

			const float t = 1 - row[fx] * scale;

			if (t <= 0)
				continue;

			dest[fx] = g_BlendPixel(dest[fx], color, t * t * strength);
		}
	}
}

// r, g, b (0 to 255) in the back surface's 16-bit format.
static WORD g_Color16(int r, int g, int b)
{
	if (CDirectDraw::Is565())
		return (WORD)(((r >> 3) << 11) | ((g >> 2) << 5) | (b >> 3));

	return (WORD)(((r >> 3) << 10) | ((g >> 3) << 5) | (b >> 3));
}

void C_VS_UI_TRIBE::SetupMenuItems()
{
	m_pC_simple_spk = new C_SPRITE_PACK(SPK_SIMPLE_INFORMATION);

	// Bottom-left, 2px up from the edge.
	const int panel_w = m_pC_simple_spk->GetWidth(SIMPLE_PANEL);
	const int panel_h = m_pC_simple_spk->GetHeight(SIMPLE_PANEL);

	Set(0, g_pUserInformation->iResolution_y - panel_h - 2, panel_w, panel_h);

	s_simple_panel.left = x;
	s_simple_panel.top = y + SIMPLE_PANEL_TOP;
	s_simple_panel.right = x + w;
	s_simple_panel.bottom = y + h;

	// The pin, a plain circle, is the only button left: the renewal panel has no menu tabs.
	m_pC_common_button_group->Add(new C_VS_UI_EVENT_BUTTON(SIMPLE_PIN_X, SIMPLE_PIN_Y,
		m_pC_simple_spk->GetWidth(SIMPLE_CIRCLE), m_pC_simple_spk->GetHeight(SIMPLE_CIRCLE),
		PUSHPIN_ID, this, SIMPLE_CIRCLE));
}

//-----------------------------------------------------------------------------
// C_VS_UI_TRIBE::GetOccludeRect
//
// The panel below its transparent top rows, or just the pin while the panel
// is hidden. The skill box is outside this window and declares itself.
//-----------------------------------------------------------------------------
bool C_VS_UI_TRIBE::GetOccludeRect(int* px0, int* py0, int* px1, int* py1) const
{
	if (IsSimplePanelShown())
	{
		*px0 = x;      *py0 = y + SIMPLE_PANEL_TOP;
		*px1 = x + w;  *py1 = y + h;
	}
	else
	{
		*px0 = x + SIMPLE_PIN_X;
		*py0 = y + SIMPLE_PIN_Y;
		*px1 = *px0 + m_pC_simple_spk->GetWidth(SIMPLE_CIRCLE);
		*py1 = *py0 + m_pC_simple_spk->GetHeight(SIMPLE_CIRCLE);
	}

	return true;
}

//-----------------------------------------------------------------------------
// C_VS_UI_TRIBE::Show
//
// The pin hides the panel outright instead of sliding it
// off the screen: the pin stays, and so does the skill box.
//-----------------------------------------------------------------------------
void	C_VS_UI_TRIBE::Show()
{
	const bool bl_panel = IsSimplePanelShown();

	if (gpC_base->m_p_DDSurface_back->Lock())
	{
		if (bl_panel)
		{
			m_pC_simple_spk->BltLocked(x, y, SIMPLE_PANEL);
			ShowDayBar();

			if (g_IsSlayerStatRingShown())
			{
				for (int i = 0; i < 3; i++)
				{
					g_DrawExpRing(m_pC_simple_spk, SIMPLE_EXP_TRACK, SIMPLE_EXP_FILL,
						x + SIMPLE_STAT_RING_COLUMN_X[i] + SIMPLE_STAT_RING_X, y + SIMPLE_SLAYER_STAT_Y + SIMPLE_STAT_RING_TOP,
						SIMPLE_STAT_RING_D, g_GetSlayerStatPermille(i));
				}
			}
		}

		m_pC_common_button_group->Show();

		gpC_base->m_p_DDSurface_back->Unlock();
	}

	g_FL2_GetDC();

	m_pC_common_button_group->ShowDescription();

	if (bl_panel)
		g_PrintColorStr(x + w / 2 - g_GetStringWidth(m_time.c_str(), gpC_base->m_chatting_pi.hfont) / 2, y + SIMPLE_TIME_Y,
			m_time.c_str(), gpC_base->m_chatting_pi, RGB_WHITE);

	g_FL2_ReleaseDC();

	if (bl_panel)
		ShowExp();

	// The skill bar is registered with the WindowManager, but its Window::Show
	// is a stub and its IsPixel always returns false - it paints here, from
	// Show2, and it is this window that decides when. So the footprint has to
	// be declared here as well, or the spread-open skill grid never covers the
	// name tags the world drew underneath it.
	//
	// This is the whole rect, so the empty cells in the ragged top row count
	// as covered too. Override C_VS_UI_SKILL::GetOccludeRect if that ever
	// shows.
	{
		int x0, y0, x1, y1;

		if (m_pC_skill->GetOccludeRect(&x0, &y0, &x1, &y1))
		{
			RECT rect;
			rect.left = x0;  rect.top = y0;  rect.right = x1;  rect.bottom = y1;

			g_FL2_OverlayOccludeRect(&rect, "skill bar");
		}
	}

	m_pC_skill->Show2();
}

//-----------------------------------------------------------------------------
// C_VS_UI_TRIBE::ShowDayBar
//
// Day runs 8-20 and night 20-8. For the four hours before each turn the next
// one fills in from the left, its sun or moon riding the edge. Needs the back
// surface locked.
//-----------------------------------------------------------------------------
void C_VS_UI_TRIBE::ShowDayBar()
{
	if (m_time.size() < 5)
		return;

	// "h:mm:ss"
	const int hour = atoi(m_time.c_str());
	const int min = atoi(m_time.c_str() + m_time.size() - 5);

	const int bar_x = (m_pC_simple_spk->GetWidth(SIMPLE_PANEL) - m_pC_simple_spk->GetWidth(SIMPLE_DAY_FRAME)) / 2;

	const bool bl_day = (hour >= 8 && hour < 20);
	const int bar = bl_day ? SIMPLE_DAY_BAR : SIMPLE_NIGHT_BAR;
	const int bar_w = m_pC_simple_spk->GetWidth(bar);

	m_pC_simple_spk->BltLocked(x + bar_x, y + SIMPLE_DAY_Y, SIMPLE_DAY_FRAME);
	m_pC_simple_spk->BltLocked(x + bar_x, y + SIMPLE_DAY_Y, bar);
	m_pC_simple_spk->BltLocked(x + bar_x + bar_w - 3, y + SIMPLE_SUN_Y, bl_day ? SIMPLE_SUN : SIMPLE_MOON);

	const int turn = bl_day ? 16 : 4;

	if (hour >= turn && hour < turn + 4)
	{
		const int next_bar = bl_day ? SIMPLE_NIGHT_BAR : SIMPLE_DAY_BAR;
		const int fill_w = bar_w * ((hour - turn) * 60 + min) / 240;

		if (fill_w > 0)
		{
			Rect rect(0, 0, fill_w, m_pC_simple_spk->GetHeight(next_bar));
			m_pC_simple_spk->BltLockedClip(x + bar_x, y + SIMPLE_DAY_Y, rect, next_bar);
		}

		m_pC_simple_spk->BltLocked(x + bar_x + fill_w - 3, y + SIMPLE_SUN_Y, bl_day ? SIMPLE_MOON : SIMPLE_SUN);
	}
}

//-----------------------------------------------------------------------------
// C_VS_UI_TRIBE::ShowSimpleStats
//
// STR/DEX/INT across the panel at row_y: each label outlined in its stat's
// colour, the value centred in the rest of its column. value_x, if given,
// gets where each value went, for a row under it. Prints, so call it with
// the DC held.
//-----------------------------------------------------------------------------
void C_VS_UI_TRIBE::ShowSimpleStats(int row_y, int* value_x)
{
	const char* label[3] =
	{
		(*g_pGameStringTable)[UI_STRING_MESSAGE_ENG_STR].GetString(),
		(*g_pGameStringTable)[UI_STRING_MESSAGE_ENG_DEX].GetString(),
		(*g_pGameStringTable)[UI_STRING_MESSAGE_ENG_INT].GetString(),
	};

	const int value[3] = { g_char_slot_ingame.STR_CUR, g_char_slot_ingame.DEX_CUR, g_char_slot_ingame.INT_CUR };

	PrintInfo& pi = gpC_base->m_chatting_pi;
	char sz_value[16];

	// with a ring, the value centres between the label and the ring
	const bool bl_rings = g_IsSlayerStatRingShown();
	const int* column_x = bl_rings ? SIMPLE_STAT_RING_COLUMN_X : SIMPLE_STAT_COLUMN_X;
	const int column_w = bl_rings ? SIMPLE_STAT_RING_X : SIMPLE_STAT_W;

	for (int i = 0; i < 3; i++)
	{
		wsprintf(sz_value, "%d", value[i]);

		const int label_w = g_GetStringWidth(label[i], pi.hfont);
		const int gap = max(4, (column_w - label_w - g_GetStringWidth(sz_value, pi.hfont)) / 2);
		const int number_x = x + column_x[i] + label_w + gap;

		g_PrintColorStrOut(x + column_x[i], y + row_y, label[i], pi, RGB_WHITE, SIMPLE_STAT_RGB[i]);
		g_PrintColorStrOut(number_x, y + row_y, sz_value, pi, SIMPLE_STAT_RGB[i], RGB_BLACK);

		if (value_x != NULL)
			value_x[i] = number_x;
	}
}

//-----------------------------------------------------------------------------
// C_VS_UI_TRIBE::GetSimpleExp
//
// What the EXP bar is out of, and how much of it is left: the server sends
// the exp still to go, not the exp earned. An advanced character levels on
// advancement exp; below that a slayer's bar is the five domains together.
//-----------------------------------------------------------------------------
void C_VS_UI_TRIBE::GetSimpleExp(__int64& goal_exp, __int64& exp_remain)
{
	goal_exp = 0;
	exp_remain = g_char_slot_ingame.EXP_REMAIN;

	if (g_char_slot_ingame.m_AdvancementLevel > 0)
	{
		goal_exp = g_pExperienceTable->GetAdvanceMent(g_char_slot_ingame.m_AdvancementLevel).GoalExp;
		return;
	}

	switch (g_eRaceInterface)
	{
	case RACE_SLAYER:
		exp_remain = 0;

		for (int d = SKILLDOMAIN_BLADE; d <= SKILLDOMAIN_ENCHANT; d++)
		{
			const int level = (*g_pSkillManager)[d].GetDomainLevel();
			const int remain = (*g_pSkillManager)[d].GetDomainExpRemain();

			if (level < 0)
				continue;

			goal_exp += (*g_pSkillManager)[d].GetExpInfo(level).GoalExp;

			if (remain > 0)		// negative once the domain can't level
				exp_remain += remain;
		}
		break;

	case RACE_VAMPIRE:
		goal_exp = g_pExperienceTable->GetVampireInfo(g_char_slot_ingame.level).GoalExp;
		break;

	case RACE_OUSTERS:
		goal_exp = g_pExperienceTable->GetOustersInfo(g_char_slot_ingame.level).GoalExp;
		break;
	}
}

//-----------------------------------------------------------------------------
// C_VS_UI_TRIBE::ShowSimpleExp
//
// The EXP bar with its label and percentage.
//-----------------------------------------------------------------------------
void C_VS_UI_TRIBE::ShowSimpleExp(int track_y, int label_y)
{
	__int64 goal_exp, exp_remain;
	GetSimpleExp(goal_exp, exp_remain);

	__int64 done = goal_exp - exp_remain;

	if (done > goal_exp)
		done = goal_exp;

	if (done < 0)
		done = 0;

	const int fill_w = m_pC_simple_spk->GetWidth(SIMPLE_EXP_FILL);
	const int fill_h = m_pC_simple_spk->GetHeight(SIMPLE_EXP_FILL);

	if (gpC_base->m_p_DDSurface_back->Lock())
	{
		m_pC_simple_spk->BltLocked(x + SIMPLE_EXP_TRACK_X, y + track_y, SIMPLE_EXP_TRACK);

		if (goal_exp > 0 && done > 0)
		{
			Rect rect(0, 0, (int)(fill_w * done / goal_exp), fill_h);
			m_pC_simple_spk->BltLockedClip(x + SIMPLE_EXP_TRACK_X + 1, y + track_y + 1, rect, SIMPLE_EXP_FILL);
		}

		gpC_base->m_p_DDSurface_back->Unlock();
	}

	g_FL2_GetDC();

	g_PrintColorStrOut(x + SIMPLE_EXP_LABEL_X, y + label_y, "EXP", gpC_base->m_chatting_pi, RGB_WHITE, RGB_BLACK);

	if (goal_exp > 0)
	{
		PrintInfo& pi = gpC_base->m_small_pi;
		char sz_percent[16];

		sprintf(sz_percent, "%.1f%%", done * 100.0 / goal_exp);

		// centred on the fill, a 14px line
		g_PrintColorStrOut(x + SIMPLE_EXP_TRACK_X + 1 + (fill_w - g_GetStringWidth(sz_percent, pi.hfont)) / 2,
			y + track_y + 3 + (fill_h - 14) / 2, sz_percent, pi, RGB_WHITE, RGB_BLACK);
	}

	g_FL2_ReleaseDC();
}

void	C_VS_UI_TRIBE::Process()
{
	PlaceSkillBox(false);
	m_pC_common_button_group->Process();
}

void	C_VS_UI_TRIBE::WindowEventReceiver(id_t event)
{
	switch (event)
	{
	case EVENT_WINDOW_MOVE:
		PlaceSkillBox(true);
		EMPTY_MOVE;
		break;
	}
}
void	C_VS_UI_TRIBE::SetSelectMenu(int tab)
{
	switch (g_eRaceInterface)
	{
	case RACE_SLAYER:
		if (tab == MENU_INFO_ID || tab == MENU_GUILD_ID || tab == MENU_COMMUNITY_ID || tab == MENU_SHOP_ID || tab == MENU_HELP_ID)
			m_selected_menu = tab;
		break;

	case RACE_VAMPIRE:
		if (tab == MENU_INFO_ID || tab == MENU_GUILD_ID || tab == MENU_COMMUNITY_ID || tab == MENU_SHOP_ID || tab == MENU_HELP_ID)
			m_selected_menu = tab;
		break;

	case RACE_OUSTERS:
		if (tab == MENU_INFO_ID || tab == MENU_GUILD_ID || tab == MENU_COMMUNITY_ID || tab == MENU_SHOP_ID || tab == MENU_HELP_ID)
			m_selected_menu = tab;
		break;
	}
}



