//-----------------------------------------------------------------------------
// C_VS_UI_TRIBE::CloseInventoryGearWindow
//
// event lock????????? ???? ?????.
//-----------------------------------------------------------------------------
bool C_VS_UI_TRIBE::CloseInventoryGearWindow()
{
	if (gpC_base->EventOccured())
		return false;

	bool inventory, gear;

	inventory = gpC_window_manager->GetShowState(GetInventoryWindow());
	gear = gpC_window_manager->GetShowState(GetGearWindow());

	if (inventory)
		HotKey_Inventory();
	if (gear)
		HotKey_Gear();

	return (inventory || gear);
}

//-----------------------------------------------------------------------------
// C_VS_UI_TRIBE::CloseSkillBook
//
// ESC closes the skills window, as it closed the old skill info.
//-----------------------------------------------------------------------------
bool C_VS_UI_TRIBE::CloseSkillBook()
{
	if (m_pC_skill_book == NULL || !m_pC_skill_book->Running())
		return false;

	m_pC_skill_book->Finish();
	return true;
}

