void	C_VS_UI_TRIBE::HotKey_Help()
{
	// The description dialog reads its pages from Data\ui\txt\Help.rpk, which this
	// build does not ship, so it opens empty. Print the keyboard/chat reference into
	// the chat window instead. FileOpenBinary picks Help.en.inf when running English.
	static MStringArray	s_helpText;
	static bool			s_bHelpLoaded = false;

	if (!s_bHelpLoaded)
	{
		s_bHelpLoaded = true;		// only attempt the load once, even if it fails

		ivfstream helpFile;
		if (FileOpenBinary(FILE_INFO_HELP_TEXT, helpFile))
		{
			s_helpText.LoadFromFile(helpFile);
			helpFile.close();
		}
	}

	const int helpLines = s_helpText.GetSize();

	if (helpLines <= 0)
	{
		OnClick_HelpTap(HELP_ID);	// no help table - fall back to the old dialog
		return;
	}

	for (int i = 0; i < helpLines; ++i)
	{
		g_pSystemMessage->Add(s_helpText[i].GetString());
	}
}


void	C_VS_UI_TRIBE::OnClick_HelpTap(id_t execidx)
{
	if (execidx < HELP_ID || execidx > GUILD_HELP_ID) return;

	// RunDescDialog ??? ?????? ????
	void* pParm = nullptr;
	switch (execidx)
	{
	case HELP_ID:			pParm = nullptr;								break;
	case CHAT_HELP_ID:		pParm = (void*)C_VS_UI_DESC_DIALOG::CHATTING;	break;
	case BATTLE_HELP_ID:	pParm = (void*)C_VS_UI_DESC_DIALOG::BATTLE;		break;
	case SKILL_HELP_ID:		pParm = (void*)C_VS_UI_DESC_DIALOG::SKILL;		break;
	case GUILD_HELP_ID:		pParm = (void*)C_VS_UI_DESC_DIALOG::GUILD;		break;
	}

	if (gC_vs_ui.IsRunningMainHelp())
	{
		gC_vs_ui.CloseDescDialog();
		gC_vs_ui.RunDescDialog(DID_HELP, pParm);
	}
	else
	{
		if (gC_vs_ui.IsRunningDescDialog())
		{
			id_t backup = m_OpenedHelpIdx;
			gC_vs_ui.CloseDescDialog();
			m_OpenedHelpIdx = backup;
		}

		if (m_OpenedHelpIdx != execidx)
		{
			gC_vs_ui.RunDescDialog(DID_HELP, pParm);
		}
		else
		{
			execidx = EXEC_MAX;
		}
	}

	m_OpenedHelpIdx = execidx;		// ?? â?? ???????? ??????.


	switch (g_eRaceInterface)
	{
	case RACE_SLAYER:	PlaySound(SOUND_SLAYER_BUTTON);		break;
	case RACE_VAMPIRE:	PlaySound(SOUND_VAMPIRE_BUTTON);	break;
	case RACE_OUSTERS:	PlaySound(SOUND_OUSTERS_INTERFACE);	break;
	}

}


