void C_VS_UI_CHATTING::SetWhisperID(char* id)
{
	if (!GetWhisperFocus())
	{
		m_sz_whisper_backup = id;
	}
	else
	{
		m_lev_chatting.EraseAll();
		m_lev_chatting.AddString(id);
		ChangeWhisperFocus();
	}
}
