void
C_VS_UI_CHATTING::AddInputString(const char* pString)
{
	if (pString != NULL)
	{
		int orgStrLen = g_GetByteLenth(m_lev_chatting.GetString(), m_lev_chatting.Size());
		int addStrLen = strlen(pString);
		if (orgStrLen + addStrLen < CHAT_INPUT_LIMIT)
			m_lev_chatting.AddString(pString);
	}
}


//-----------------------------------------------------------------------------
// g_LogChatDraw
//
// Diagnostic. A black box has drawn at the chat's bottom-left: once the
// pop-up panel's art, empty and solid, while the chat line was closed, and
// once a smaller dark box over the button column. Log\chat_draw.log gets a
// line whenever what the chat is drawing changes, so the next one shows the
// state that drew it. `which` keeps each call site's last state apart.
//-----------------------------------------------------------------------------
static void g_LogChatDraw(int which, const char* sz_where, const int* state, int count, const char* sz_line)
{
	enum { SITES = 2, STATE_MAX = 16, LINES_MAX = 2000 };
	static int s_last[SITES][STATE_MAX];
	static bool s_bl_logged[SITES] = { false, false };
	static int s_lines = 0;

	if (which < 0 || which >= SITES || count > STATE_MAX || s_lines >= LINES_MAX)
		return;
	if (s_bl_logged[which] && memcmp(s_last[which], state, count * sizeof(int)) == 0)
		return;

	memcpy(s_last[which], state, count * sizeof(int));
	s_bl_logged[which] = true;

	FILE* f = fopen("Log\\chat_draw.log", "a");
	if (f == NULL)
		return;
	SYSTEMTIME st;
	GetLocalTime(&st);
	fprintf(f, "%04d-%02d-%02d %02d:%02d:%02d.%03d %-6s %s\n", st.wYear, st.wMonth, st.wDay,
		st.wHour, st.wMinute, st.wSecond, st.wMilliseconds, sz_where, sz_line);
	fclose(f);
	if (++s_lines == LINES_MAX)
	{
		f = fopen("Log\\chat_draw.log", "a");
		if (f != NULL)
		{
			fprintf(f, "(stopped logging after %d lines)\n", (int)LINES_MAX);
			fclose(f);
		}
	}
}

/*-----------------------------------------------------------------------------
- Show
-
-----------------------------------------------------------------------------*/
void C_VS_UI_CHATTING::Show()
{
	int gap = 0;
	const bool panel_open = IsPanelOpen();

	{
		// diagnostic: the state this frame draws from
		const int state[] = { m_sub_window, panel_open, m_bl_input_mode, g_pUserOption->UseEnterChat,
			m_bl_menu_open, m_bl_spreadID, GetAttributes()->autohide, x, y, w, h, m_sub_rect.x, m_sub_rect.y, m_sub_rect.w, m_sub_rect.h };
		char sz_line[256];
		sprintf(sz_line, "sub_window=%d panel_open=%d input_mode=%d enter_chat=%d menu_open=%d spread=%d autohide=%d "
			"chat=(%d,%d %dx%d) sub_rect=(%d,%d %dx%d)", state[0], state[1], state[2], state[3], state[4], state[5], state[6],
			state[7], state[8], state[9], state[10], state[11], state[12], state[13], state[14]);
		g_LogChatDraw(0, "state", state, sizeof(state) / sizeof(state[0]), sz_line);
	}
	if (gpC_base->m_p_DDSurface_back->Lock())
	{
		if (!panel_open)
		{
			// Enter-chat mode with the line closed: only the button column shows
			m_bl_menu_open = false;
			m_bl_spreadID = false;
			m_sub_window = 0;
		}
		else
		{
			gap = CHAT_INPUT_BAR_H;

			// The open chat is a plain half-dark panel that rounds its two
			// right-hand corners (the left edge sits on the screen edge). DrawAlphaBox
			// rects are right/bottom exclusive, so the pieces never overlap.
			static const int corner_inset[CHAT_CORNER_R] = { 5, 3, 2, 1, 1 };

			RECT body = { x, y, x + w - CHAT_CORNER_R, y + h };
			DrawAlphaBox(&body, 0, 0, 0, 15);
			RECT strip = { x + w - CHAT_CORNER_R, y + CHAT_CORNER_R, x + w, y + h - CHAT_CORNER_R };
			DrawAlphaBox(&strip, 0, 0, 0, 15);
			for (int r = 0; r < CHAT_CORNER_R; ++r)
			{
				if (corner_inset[r] >= CHAT_CORNER_R)
					continue;
				RECT top = { x + w - CHAT_CORNER_R, y + r, x + w - corner_inset[r], y + r + 1 };
				RECT bottom = { x + w - CHAT_CORNER_R, y + h - 1 - r, x + w - corner_inset[r], y + h - r };
				DrawAlphaBox(&top, 0, 0, 0, 15);
				DrawAlphaBox(&bottom, 0, 0, 0, 15);
			}

			// Input bar, 28 middle rows of the 38px art: the left cap's button panel,
			// the cap's field edge, the field, and the right cap's first 15 columns.
			const int band_y = y + h - gap - CHAT_INPUT_ART_TOP;
			const int left_w = m_pC_chatting_spk->GetWidth(RENEWAL_INPUT_LEFT);
			const int field_x = x + CHAT_INPUT_FIELD_X;
			const int right_x = x + w - 15;

			Rect band(0, CHAT_INPUT_ART_TOP, CHAT_INPUT_FIELD_X - 4 - CHAT_COLUMN_W, gap);
			m_pC_chatting_spk->BltLockedClip(x + CHAT_COLUMN_W, band_y, band, RENEWAL_INPUT_LEFT);

			band.x = left_w - 4;
			band.w = 4;
			m_pC_chatting_spk->BltLockedClip(field_x - left_w, band_y, band, RENEWAL_INPUT_LEFT);

			band.x = 0;
			band.w = min(m_pC_chatting_spk->GetWidth(RENEWAL_INPUT_MIDDLE), right_x - field_x);
			if (band.w > 0)
				m_pC_chatting_spk->BltLockedClip(field_x, band_y, band, RENEWAL_INPUT_MIDDLE);

			// the right cap's first 15 columns, its bottom rows trimmed to the rounded corner
			band.w = 15;
			band.h = gap - CHAT_CORNER_R;
			m_pC_chatting_spk->BltLockedClip(right_x, band_y, band, RENEWAL_INPUT_RIGHT);
			for (int r = 0; r < CHAT_CORNER_R; ++r)
			{
				Rect slice(0, CHAT_INPUT_ART_TOP + gap - 1 - r, 15 - corner_inset[r], 1);
				m_pC_chatting_spk->BltLockedClip(right_x, band_y, slice, RENEWAL_INPUT_RIGHT);
			}

			m_pC_input_button_group->Show();

			// the channel being typed into, as its lit tab
			const int mode = m_bl_whisper_mode ? (int)CLD_WHISPER : (int)m_chat_mode;
			if (mode >= CLD_NORMAL && mode <= CLD_UNION)
			{
				const int tab = RENEWAL_TAB_NORMAL + mode * 2 + 1;
				m_pC_chatting_spk->BltLocked(x + CHAT_MODE_TAB_X, y + h - gap + (gap - m_pC_chatting_spk->GetHeight(tab)) / 2, tab);
			}

			if (m_bl_menu_open)
				m_pC_menu_button_group->Show();
		}
		m_pC_button_group->Show();


		if (m_sub_window != 0)
		{
			// channel settings open over the left end, the pickers over the right;
			// above the chat when there is room, else below it
			m_sub_rect.x = (m_sub_window == 3) ? x : x + w - m_sub_rect.w;
			if (y > m_sub_rect.h + 5)
				m_sub_rect.y = y - m_sub_rect.h - 5;
			else
				m_sub_rect.y = y + h;

			RECT dialog = { m_sub_rect.x + 4, m_sub_rect.y + 5,
				m_sub_rect.x + 4 + m_pC_chatting_spk->GetWidth(RENEWAL_DIALOG),
				m_sub_rect.y + 5 + m_pC_chatting_spk->GetHeight(RENEWAL_DIALOG) };
			{
				// diagnostic: where the pop-up panel's art goes, and for what
				const int state[] = { m_sub_window, panel_open, dialog.left, dialog.top, dialog.right, dialog.bottom };
				char sz_line[160];
				sprintf(sz_line, "sub_window=%d panel_open=%d dialog=(%d,%d)-(%d,%d)", state[0], state[1], state[2], state[3], state[4], state[5]);
				g_LogChatDraw(1, "dialog", state, sizeof(state) / sizeof(state[0]), sz_line);
			}
			g_FL2_OverlayOccludeRect(&dialog, "ChatDialog");
			m_pC_chatting_spk->BltLockedAlpha(dialog.left, dialog.top, RENEWAL_DIALOG, 20);

			if (m_sub_window == 1)	// mark
			{
				if (m_sub_selected.x != -1)
				{
					RECT rect = { m_sub_rect.x + MARK_X + m_sub_selected.x * 14 - 1, m_sub_rect.y + MARK_Y - 2 + (m_sub_selected.y - m_pC_sub_scroll_bar->GetScrollPos()) * 14, 0, 0 };
					rect.right = rect.left + 15;
					rect.bottom = rect.top + 16;

					if (m_sub_selected.y >= m_pC_sub_scroll_bar->GetScrollPos() && m_sub_selected.y < m_pC_sub_scroll_bar->GetScrollPos() + 5)
						DrawAlphaBox(&rect, 0, 0, 255, g_pUserOption->ALPHA_DEPTH);
				}
				gpC_base->m_p_DDSurface_back->Unlock();
				int localLine = 1;
	#if __CONTENTS(__JAPAN_UI)
				localLine = 0;
	#endif //__JAPAN_UI

				g_FL2_GetDC();
				for (int i = 0; i < MARK_MAX - localLine; i++)
				{
					for (int j = 0; j < 9; j++)
					{
						int scrollPos = m_pC_sub_scroll_bar->GetScrollPos();
						if (scrollPos < 0)
							scrollPos = 0;
						g_PrintColorStr(m_sub_rect.x + j * 14 + MARK_X, m_sub_rect.y + i * 14 + MARK_Y, g_mark[i + scrollPos][j], gpC_base->m_chatting_pi, RGB_WHITE);
					}
				}
				g_FL2_ReleaseDC();
				m_pC_sub_scroll_bar->Show(m_sub_rect.x, m_sub_rect.y);
			}
			else if (m_sub_window == 2)	// color
			{
				gpC_base->m_p_DDSurface_back->Unlock();
				RECT rect;
				for (int i = 0; i < 4; i++)
				{
					for (int j = 0; j < 4; j++)
					{
						rect.left = m_sub_rect.x + j * 30 + COLOR_X;
						rect.top = m_sub_rect.y + i * 17 + COLOR_Y;
						rect.right = rect.left + 28;
						rect.bottom = rect.top + 15;
						COLORREF color = g_color[i][j];
						BYTE b = (color & 0xff0000) >> 19;
						BYTE g = (color & 0xff00) >> 11;
						BYTE r = (color & 0xff) >> 3;
						WORD c = CDirectDraw::Color(r, g, b);
						gpC_base->m_p_DDSurface_back->FillRect(&rect, c);
					}
				}
				if (m_sub_selected.x != -1)
				{
					gpC_global_resource->m_pC_scroll_bar_spk->Blt(m_sub_rect.x + COLOR_X + m_sub_selected.x * 30, m_sub_rect.y + COLOR_Y + m_sub_selected.y * 17, C_GLOBAL_RESOURCE::SB_BUTTON);
				}
			}
			else if (m_sub_window == 3)	// channel settings
			{
				// the "chat invisible settings": which channels the history
				// shows, in m_chat_filter order (normal, zone / whisper, party /
				// guild, union)
				for (int i = 0; i < 6; ++i)
					m_pC_chatting_spk->BltLocked(m_sub_rect.x + SETTING_CELL_X + (i % 2) * SETTING_CELL_W,
						m_sub_rect.y + SETTING_CELL_Y + (i / 2) * SETTING_CELL_H,
						m_chat_filter[i] ? RENEWAL_FILTER_ON : RENEWAL_FILTER_OFF);
				gpC_base->m_p_DDSurface_back->Unlock();

				const char* guild = (g_eRaceInterface == RACE_SLAYER) ? "Team" : (g_eRaceInterface == RACE_VAMPIRE) ? "Clan" : "Guild";
				const char* label[6] = { "Normal", "Zone", "Whisper", "Party", guild, "Union" };

				g_FL2_GetDC();
				g_PrintColorStr(m_sub_rect.x + 12, m_sub_rect.y + 8, "Visible Channels", gpC_base->m_chatting_pi, RGB(130, 230, 230));
				for (int i = 0; i < 6; ++i)
					g_PrintColorStr(m_sub_rect.x + SETTING_CELL_X + (i % 2) * SETTING_CELL_W + 15,
						m_sub_rect.y + SETTING_CELL_Y + (i / 2) * SETTING_CELL_H - 3,
						label[i], gpC_base->m_chatting_pi, m_chat_filter[i] ? RGB_WHITE : RGB(128, 128, 128));
				g_FL2_ReleaseDC();
			}
			else
				gpC_base->m_p_DDSurface_back->Unlock();
		}
		else
			gpC_base->m_p_DDSurface_back->Unlock();
	}

	// ????? ???? ???? ??????? ??? ???. process ?? ??? by  sonee

	// Ÿ???? ??? ????? GRAY,RED ??????????. process ?? ??? by sonee

	// Ÿ???? ?°? ???? ????? ???????? ???. process ?? ???  by sonee


	if (!g_pUserOption->UseEnterChat || m_bl_input_mode)
	{
		// ?????? ?????? ??? ????? ?????? ???? ?? ????
		bool bFoundMute = false;
		S_SLOT::UI_EFFECTSTATUS_TYPE::iterator itr = g_char_slot_ingame.STATUS.begin();
		S_SLOT::UI_EFFECTSTATUS_TYPE::iterator endItr = g_char_slot_ingame.STATUS.end();
		while (itr != endItr)
		{
			if (itr->actionInfo == SKILL_MUTE)
			{
				bFoundMute = true;
				break;
			}
			itr++;
		}

		if (bFoundMute && !g_pUserInformation->attrOperator.GetValue())
		{
			if (m_bl_whisper_mode)
				g_PrintColorStr(CHAT_INPUT_START_X + 100, CHAT_LINE_START_Y, (*g_pGameStringTable)[UI_STRING_MESSAGE_MUTE].GetString(), gpC_base->m_chatting_pi, RGB_RED);
			else
				g_PrintColorStr(CHAT_INPUT_START_X, CHAT_LINE_START_Y, (*g_pGameStringTable)[UI_STRING_MESSAGE_MUTE].GetString(), gpC_base->m_chatting_pi, RGB_RED);
		}
		else
			if (m_timer == TIMER_REP || m_timer == TIMER_PAPERING)
			{
				if (m_bl_whisper_mode)
					g_PrintColorStr(CHAT_INPUT_START_X + 100, CHAT_LINE_START_Y, (*g_pGameStringTable)[UI_STRING_MESSAGE_LIMIT_STRING_COUNT].GetString(), gpC_base->m_chatting_pi, RGB_RED);
				else
					g_PrintColorStr(CHAT_INPUT_START_X, CHAT_LINE_START_Y, (*g_pGameStringTable)[UI_STRING_MESSAGE_LIMIT_STRING_COUNT].GetString(), gpC_base->m_chatting_pi, RGB_RED);
			}
			else
			{
				if (g_pUserOption->ChatWhite)
					m_lev_chatting.SetInputStringColor(gpC_base->m_chatting_pi.text_color);
				else
					if (!IsCannotSendChatInput())				// Chating Color Setting. Timer....(???? ?? ?? ä?ý? ????)
						m_lev_chatting.SetInputStringColor(g_pUserOption->ChattingColor);
				m_lev_chatting.Show();
			}
	}
	g_FL2_GetDC();

	//////////////////////////////////////////////////////////////////////////
	//by chaya & diesirace
	//////////////////////////////////////////////////////////////////////////
	int line = 0;

	for (int i = 0, scroll = 0;
		i < m_pC_history_list.Size() && line < g_HISTORY_LINE; /*++line,*/ ++i)
	{
		C_VS_UI_CHAT_LINE* p_line;
		p_line = m_pC_history_list.GetLine(i);
		const int _ID_GAP = 2;

		if (p_line)
		{
			if (m_chat_filter[p_line->GetCondition()] == false)
			{
				/*--line;*/
				continue;
			}

			if (p_line->GetMsgString())
			{
				char* p_temp = (char*)p_line->GetMsgString();
				int	cut_length = 0;

				if (p_line->GetCondition() == CLD_ZONECHAT)
				{
					// ?????~~!!! ????????????!!!!
					// BOLD?? ????????? ?????? ??????? ?????? ?????????-??-					
					char sz_temp[130];
					int smart_size = CHAT_WINDOW_WIDTH - g_GetStringWidth(p_line->GetIdString(), gpC_base->m_user_id_pi.hfont) - g_GetStringWidth(g_sz_chat_id_divisor[p_line->GetCondition()], gpC_base->m_chatting_pi.hfont) - _ID_GAP;
					cut_length = strlen(p_temp);
					if (g_GetStringWidth(p_temp, gpC_base->m_user_id_pi.hfont) > smart_size)
					{
						strcpy(sz_temp, p_temp);
						while (g_GetStringWidth(sz_temp, gpC_base->m_user_id_pi.hfont) > smart_size)
						{
							sz_temp[cut_length--] = '\0';
						}
					}
				}
				else
				{
					cut_length =
						(CHAT_WINDOW_WIDTH -
							g_GetStringWidth(p_line->GetIdString(), gpC_base->m_user_id_pi.hfont) -
							g_GetStringWidth(g_sz_chat_id_divisor[p_line->GetCondition()], gpC_base->m_chatting_pi.hfont) -
							_ID_GAP) / (g_GetStringWidth("F", gpC_base->m_chatting_pi.hfont));
				}

				int vx = CHAT_LINE_START_X;
				vx += g_GetStringWidth(p_line->GetIdString(), gpC_base->m_user_id_pi.hfont);
				vx += g_GetStringWidth(g_sz_chat_id_divisor[p_line->GetCondition()], gpC_base->m_chatting_pi.hfont);
				vx += _ID_GAP;

				std::vector<int> CutLenghtVec;

				int str_length = strlen(p_temp);

				// word-aware split; the lengths add up to str_length
				s_ChatCutLengths(p_temp, cut_length, CutLenghtVec);

				int	loopCnt = CutLenghtVec.size() - 1;

				const char* pDrawStr = p_temp + str_length;

				for (;
					line < g_HISTORY_LINE && line >= 0 && loopCnt >= 0;
					--loopCnt, ++line)
				{
					PrintInfo* pi;

					if (p_line->GetCondition() == CLD_ZONECHAT)
						pi = &gpC_base->m_user_id_pi;
					else
						pi = &gpC_base->m_chatting_pi;


					if (scroll < m_pC_scroll_bar->GetScrollPos())
					{
						++scroll;
						--line;
						if (scroll <= m_pC_scroll_bar->GetScrollPos())
							continue;
					}

					int curr_length = CutLenghtVec[loopCnt];

					pDrawStr -= curr_length;

					if (loopCnt == 0 && p_line->GetIdString())
					{
						int tabvalue = 0;
						if (strstr(p_line->GetIdString(), (*g_pGameStringTable)[UI_STRING_MESSAGE_MASTER_NAME].GetString()) != NULL)
							tabvalue = CLD_MASTER;
						else
							tabvalue = p_line->GetCondition();

						const int ly = CHAT_HISTORY_START_Y - (FONT_GAP * line);
						if (panel_open)
						{
							vx = g_PrintColorStr(CHAT_LINE_START_X, ly, p_line->GetIdString(), gpC_base->m_user_id_pi, m_color_tab[tabvalue]);
							vx = g_PrintColorStr(vx, ly, g_sz_chat_id_divisor[p_line->GetCondition()], gpC_base->m_chatting_pi, m_color_tab[tabvalue]);
						}
						else
						{
							// no panel behind the text: shadowed
							vx = g_PrintColorStrShadow(CHAT_LINE_START_X, ly, p_line->GetIdString(), gpC_base->m_user_id_pi, m_color_tab[tabvalue]);
							vx = g_PrintColorStrShadow(vx, ly, g_sz_chat_id_divisor[p_line->GetCondition()], gpC_base->m_chatting_pi, m_color_tab[tabvalue]);
						}
						vx += _ID_GAP;
					}

					if (panel_open)
						g_PrintColorStrLen(vx, CHAT_HISTORY_START_Y - (FONT_GAP * line),
							pDrawStr, curr_length, *pi, p_line->GetColor());
					else
					{
						char shadowed[512];
						const int n = min(curr_length, (int)sizeof(shadowed) - 1);
						memcpy(shadowed, pDrawStr, n);
						shadowed[n] = '\0';
						g_PrintColorStrShadow(vx, CHAT_HISTORY_START_Y - (FONT_GAP * line), shadowed, *pi, p_line->GetColor());
					}
				}
			}
		}
	}

	if (gap)
	{
		m_pC_input_button_group->ShowDescription();
		if (m_bl_menu_open)
			m_pC_menu_button_group->ShowDescription();
	}
	m_pC_button_group->ShowDescription();

	g_FL2_ReleaseDC();

	if (m_bl_whisper_mode && (!g_pUserOption->UseEnterChat || m_bl_input_mode))
	{
		if (m_bl_spreadID)
		{

			RECT rect = { CHAT_INPUT_START_X, CHAT_LINE_START_Y - GetWhisperSize() * FONT_GAP - 3, CHAT_INPUT_START_X + 70, CHAT_LINE_START_Y - 3 };
			DrawAlphaBox(&rect, 50 >> 3, 50 >> 3, 150 >> 3, 25);
			g_FL2_GetDC();
			for (int i = 0; i < GetWhisperSize(); i++)
			{
				g_PrintColorStr(CHAT_INPUT_START_X, CHAT_LINE_START_Y - GetWhisperSize() * FONT_GAP + i * FONT_GAP, GetWhisperID(i).c_str(), gpC_base->m_user_id_pi, gpC_base->m_user_id_pi.text_color);
			}
			g_FL2_ReleaseDC();

			//			g_PrintColorStr(CHAT_LINE_START_X +90, CHAT_LINE_START_Y, "v", gpC_base->m_user_id_pi, gpC_base->m_user_id_pi.text_color);
		}// else g_PrintColorStr(CHAT_LINE_START_X +90, CHAT_LINE_START_Y, "^", gpC_base->m_user_id_pi, gpC_base->m_user_id_pi.text_color);

		if (m_bl_focus_whisper)
		{
			//if(m_sz_whisper_backup.size() > 0)     ###@@@
			if (!m_sz_whisper_backup.empty())
			{

				int len = m_sz_whisper_backup.size();
				int len2 = m_lev_chatting.ReachSizeOfBox() + 1;

				// Used to draw with a raw surface GetDC (which bypasses the
				// FL2 dirty tracking and the native-res overlay, and can hand
				// back an invalid DC on 16-bit surfaces). Route through FL2.
				g_PrintColorStrLen(CHAT_INPUT_START_X + 100, CHAT_LINE_START_Y,
					m_sz_whisper_backup.c_str(), min(len, len2),
					gpC_base->m_chatting_pi, m_color_tab[CLD_NORMAL]);
			}
		}
		else
		{
			//if(m_sz_whisper_backup.size() > 0) ###@@@
			if (!m_sz_whisper_backup.empty())
				g_PrintColorStr(CHAT_INPUT_START_X, CHAT_LINE_START_Y, m_sz_whisper_backup.c_str(), gpC_base->m_user_id_pi, gpC_base->m_user_id_pi.text_color);
		}
	}

	//*
#ifndef _LIB
	//	if (gpC_base->m_p_DDSurface_back->Lock())
	//	{
	//		S_SURFACEINFO	surfaceinfo;
	//		SetSurfaceInfo(&surfaceinfo, gpC_base->m_p_DDSurface_back->GetDDSD());

	//		Rect rect;

	//rect.Set(CHAT_LINE_START_X, CHAT_LINE_START_Y, 100, 15);
	//rectangle(&surfaceinfo, &rect, WHITE);

	// -- TEST
	// show scroll button rect.
	//
	//rectangle(&surfaceinfo, SCROLL_UP_X, SCROLL_UP_Y, SCROLL_UP_X+SCROLL_W-1, SCROLL_UP_Y+SCROLL_H-1, 0xFFFF);
	//rectangle(&surfaceinfo, SCROLL_DOWN_X, SCROLL_DOWN_Y, SCROLL_DOWN_X+SCROLL_W-1, SCROLL_DOWN_Y+SCROLL_H-1, 0xFFFF);

	//rectangle(&surfaceinfo, SCROLLTAG_X, SCROLLTAG_Y, SCROLLTAG_X+SCROLLTAG_W-1, SCROLLTAG_Y+SCROLLTAG_H-1, 0xFFFF);

	//rectangle(&surfaceinfo, SCROLLTRACK_X, SCROLLTRACK_Y, SCROLLTRACK_X+SCROLLTRACK_W-1, SCROLLTRACK_Y+SCROLLTRACK_H-1, 0xFFFF);

	//		gpC_base->m_p_DDSurface_back->Unlock();
	//	}
	extern bool gbl_info_show;

	if (gbl_info_show)
	{
		char sz_buf[100];

		sprintf(sz_buf, "m_pC_history_list = %d", m_pC_history_list.Size());
		g_Print(5, TEXT_LINE(16), sz_buf);
		sprintf(sz_buf, "m_pC_history_temp_list = %d", m_pC_history_temp_list.Size());
		g_Print(5, TEXT_LINE(17), sz_buf);

		sprintf(sz_buf, "GetWhisperSize() = %d", GetWhisperSize());
		g_Print(5, TEXT_LINE(20), sz_buf);
		sprintf(sz_buf, "m_whisper_index = %d", m_whisper_index);
		g_Print(5, TEXT_LINE(21), sz_buf);
		sprintf(sz_buf, "g_HISTORYLINE = %d", g_HISTORY_LINE);
		g_Print(5, TEXT_LINE(22), sz_buf);


	}
#endif
	//*/
}

