//-----------------------------------------------------------------------------
// C_VS_UI_INVENTORY::Timer
//
//-----------------------------------------------------------------------------
bool	C_VS_UI_INVENTORY::Timer(bool reset)
{
	if (reset)
	{
		gi_mine_progress = GetTickCount();
	}
	else if (gi_mine_progress + m_dw_millisec <= GetTickCount())
	{
		gi_mine_progress = GetTickCount();
		return true;
	}

	return false;
}


