{
	PI_Processor::Start();

	gpC_window_manager->AppearWindow(this);

	m_bl_pushed = false;
	m_bl_focused = false;
}

//-----------------------------------------------------------------------------
// C_VS_UI_LEVELUP::Finish
//
// 
//-----------------------------------------------------------------------------
void C_VS_UI_LEVELUP::Finish()
{
	PI_Processor::Finish();

	gpC_window_manager->DisappearWindow(this);
}

//-----------------------------------------------------------------------------
// C_VS_UI_LEVELUP::MouseControl
//
// 
//-----------------------------------------------------------------------------
bool	C_VS_UI_LEVELUP::MouseControl(UINT message, int _x, int _y)
{
	Window::MouseControl(message, _x, _y);

	switch (message)
	{
	case M_MOVING:
		m_bl_focused = true;
		break;

	case M_LEFTBUTTON_DOWN:
	case M_LB_DOUBLECLICK:
		if (m_bl_focused)
			m_bl_pushed = true;
		break;

	case M_LEFTBUTTON_UP:
		if (m_bl_pushed)
		{
			// the new character window, without the inventory (user 2026-09-17);
			// it was the old character sheet C_VS_UI_INFO
			gC_vs_ui.OpenGearWindow();

			if (g_eRaceInterface == RACE_SLAYER)
				gpC_base->SendMessage(UI_FINISH_LEVELUP_BUTTON);
		}

		m_bl_pushed = false;
		break;
	}

	return true;
}

