				m_image_spk.BltLocked(x + pad, y + pad, RESURRECT_SLAYER);
				break;

			case RACE_VAMPIRE:
				m_image_spk.BltLocked(x + pad, y + pad, RESURRECT_VAMPIRE);
				break;

			case RACE_OUSTERS:
