//-----------------------------------------------------------------------------
// C_VS_UI_HPBAR::ComputeOpaqueBounds
//
// The renewal bar sprites are mostly transparent - the 510x37 horizontal art
// paints a band about 24px tall with a clear strip above it - so the Window
// rect is a poor stand-in for what the bar covers. Scan each of the four main
// sprites once for the box around its painted pixels.
//-----------------------------------------------------------------------------
void C_VS_UI_HPBAR::ComputeOpaqueBounds()
{
	int small_offset = 0;
	switch (g_eRaceInterface)
	{
	case RACE_SLAYER:	small_offset = SLAYER_MAX;		break;
	case RACE_VAMPIRE:	small_offset = VAMPIRE_MAX;	break;
	case RACE_OUSTERS:	small_offset = OUSTERS_MAX;	break;
	}

	const int sprite[4] =
	{
		MAIN_WIDTH,
		MAIN_HEIGHT,
		MAIN_WIDTH + small_offset,
		MAIN_HEIGHT + small_offset,
	};

	for (int i = 0; i < 4; ++i)
	{
		const int sw = m_pC_hpbar_spk->GetWidth(sprite[i]);
		const int sh = m_pC_hpbar_spk->GetHeight(sprite[i]);

		RECT& rc = m_rcOpaque[i];
		rc.left = sw;  rc.top = sh;  rc.right = 0;  rc.bottom = 0;

		for (int py = 0; py < sh; ++py)
			for (int px = 0; px < sw; ++px)
				if (m_pC_hpbar_spk->IsPixel(px, py, sprite[i]))
				{
					if (px < rc.left)			rc.left   = px;
					if (py < rc.top)			rc.top    = py;
					if (px + 1 > rc.right)		rc.right  = px + 1;
					if (py + 1 > rc.bottom)		rc.bottom = py + 1;
				}

		// nothing painted at all: fall back to the whole sprite rather than nothing
		if (rc.right <= rc.left || rc.bottom <= rc.top)
			SetRect(&rc, 0, 0, sw, sh);

		ComputeGlowField(sprite[i], m_glow_field[i]);
	}
}

//-----------------------------------------------------------------------------
// C_VS_UI_HPBAR::ComputeGlowField
//
// The distance field the safe-zone halo draws from, so it hugs the bar's
// cut corners instead of boxing them in. Every painted pixel on the art's
// edge writes its distance into the clear pixels within GLOW_WIDTH of it,
// keeping the smallest; painted pixels and anything further away stay 255.
//-----------------------------------------------------------------------------
void C_VS_UI_HPBAR::ComputeGlowField(int sprite, std::vector<BYTE>& field)
{
	const int sw = m_pC_hpbar_spk->GetWidth(sprite);
	const int sh = m_pC_hpbar_spk->GetHeight(sprite);
	const int w = sw + GLOW_WIDTH * 2;
	const int h = sh + GLOW_WIDTH * 2;

	field.assign(w * h, 255);

	std::vector<BYTE> mask(sw * sh);

	for (int py = 0; py < sh; py++)
		for (int px = 0; px < sw; px++)
			mask[py * sw + px] = m_pC_hpbar_spk->IsPixel(px, py, sprite) ? 1 : 0;

	// distance from a pixel to another dx, dy away, in sixteenths
	static BYTE splat[GLOW_WIDTH * 2 + 1][GLOW_WIDTH * 2 + 1];
	static bool bl_splat = false;

	if (!bl_splat)
	{
		for (int dy = -GLOW_WIDTH; dy <= GLOW_WIDTH; dy++)
			for (int dx = -GLOW_WIDTH; dx <= GLOW_WIDTH; dx++)
			{
				const float d = sqrtf((float)(dx * dx + dy * dy)) * 16;
				splat[dy + GLOW_WIDTH][dx + GLOW_WIDTH] = (BYTE)min(255, (int)d);
			}
		bl_splat = true;
	}

	for (int py = 0; py < sh; py++)
	{
		for (int px = 0; px < sw; px++)
		{
			if (!mask[py * sw + px])
				continue;

			// only the art's edge matters: a painted pixel with a clear
			// neighbour, or one on the sprite's border
			const bool bl_edge = px == 0 || py == 0 || px == sw - 1 || py == sh - 1 ||
				!mask[py * sw + px - 1] || !mask[py * sw + px + 1] ||
				!mask[(py - 1) * sw + px] || !mask[(py + 1) * sw + px];

			if (!bl_edge)
				continue;

			for (int dy = -GLOW_WIDTH; dy <= GLOW_WIDTH; dy++)
			{
				const int qy = py + dy;

				for (int dx = -GLOW_WIDTH; dx <= GLOW_WIDTH; dx++)
				{
					const int qx = px + dx;

					if (qx >= 0 && qy >= 0 && qx < sw && qy < sh && mask[qy * sw + qx])
						continue;	// painted: no halo there

					BYTE& cell = field[(qy + GLOW_WIDTH) * w + qx + GLOW_WIDTH];
					const BYTE d = splat[dy + GLOW_WIDTH][dx + GLOW_WIDTH];

					if (d < cell)
						cell = d;
				}
			}
		}
	}
}

int C_VS_UI_HPBAR::MainSpriteIndex() const
{
	return (m_width_mode ? MAIN_WIDTH : MAIN_HEIGHT) + m_small_offset;
}

ButtonGroup* C_VS_UI_HPBAR::CurrentButtonGroup() const
{
	if (m_width_mode)
		return m_small_mode ? m_pC_small_width_button_group : m_pC_width_button_group;

	return m_small_mode ? m_pC_small_height_button_group : m_pC_height_button_group;
}

//-----------------------------------------------------------------------------
// C_VS_UI_HPBAR::GetOccludeRect
//
// Report only what the bar paints - the opaque box of the current main sprite,
// grown to take in the change/resize gems, which sit just outside the frame
// art - instead of the whole Window rect. Text beside the bar, like the chat
// line just above it, then stays visible.
//-----------------------------------------------------------------------------
bool C_VS_UI_HPBAR::GetOccludeRect(int* px0, int* py0, int* px1, int* py1) const
{
	RECT rc = m_rcOpaque[(m_width_mode ? 0 : 1) + (m_small_mode ? 2 : 0)];

	const ButtonGroup* p_group = CurrentButtonGroup();
	if (p_group != NULL)
	{
		C_VS_UI_EVENT_BUTTON* p_button;

		for (int i = 0; i < p_group->Size(); ++i)
		{
			if (!p_group->Data(i, p_button) || p_button->m_image_index < 0)
				continue;

			const int bx1 = p_button->x + m_pC_hpbar_spk->GetWidth(p_button->m_image_index);
			const int by1 = p_button->y + m_pC_hpbar_spk->GetHeight(p_button->m_image_index);

			if (p_button->x < rc.left)		rc.left   = p_button->x;
			if (p_button->y < rc.top)		rc.top    = p_button->y;
			if (bx1 > rc.right)				rc.right  = bx1;
			if (by1 > rc.bottom)			rc.bottom = by1;
		}
	}

	*px0 = x + rc.left;   *py0 = y + rc.top;
	*px1 = x + rc.right;  *py1 = y + rc.bottom;
	return rc.right > rc.left && rc.bottom > rc.top;
}

//-----------------------------------------------------------------------------
// C_VS_UI_HPBAR::ShowSafeZoneGlow
//
// While the player stands in a sector the minimap paints green, a green
// halo breathes round the bar's art: an 8px fade hugging its painted edge,
// swelling and easing over about two seconds so it reads as a state, not
// a frame. It comes up in a third of a second on entering the zone and
// takes most of a second to die away on leaving. A town that is safe
// throughout gets no halo - that is not what the minimap shows either.
//-----------------------------------------------------------------------------
void C_VS_UI_HPBAR::ShowSafeZoneGlow()
{
	static const DWORD GLOW_PERIOD = 2000;	// ms per breath
	static const float GLOW_FADE_IN = 0.3f;	// seconds, off to full
	static const float GLOW_FADE_OUT = 0.8f;	// seconds, full to off

	// step the level toward where it is headed; a long gap (the bar was
	// hidden) counts as a short one so it never jumps
	const DWORD now = GetTickCount();
	const float dt = min(0.1f, (now - m_glow_tick) / 1000.0f);
	m_glow_tick = now;

	if (IsPlayerInSectorSafeZone())
		m_glow_level = min(1.0f, m_glow_level + dt / GLOW_FADE_IN);
	else
		m_glow_level = max(0.0f, m_glow_level - dt / GLOW_FADE_OUT);

	if (m_glow_level <= 0)
		return;

	const float phase = (now % GLOW_PERIOD) * 6.2831853f / GLOW_PERIOD;
	const float strength = (0.55f + 0.30f * sinf(phase)) * m_glow_level;

	const int index = (m_width_mode ? 0 : 1) + (m_small_mode ? 2 : 0);
	const std::vector<BYTE>& field = m_glow_field[index];
	const int w = m_pC_hpbar_spk->GetWidth(MainSpriteIndex()) + GLOW_WIDTH * 2;
	const int h = m_pC_hpbar_spk->GetHeight(MainSpriteIndex()) + GLOW_WIDTH * 2;

	if ((int)field.size() != w * h)
		return;

	g_DrawGlowField(&field[0], w, h, x - GLOW_WIDTH, y - GLOW_WIDTH, g_Color16(64, 255, 96), GLOW_WIDTH, strength);
}

//-----------------------------------------------------------------------------
// C_VS_UI_HPBAR::IsPixel
//
// Only the painted art and the gems take the mouse, so clicks on the clear
// parts of the bar reach whatever is behind it.
//-----------------------------------------------------------------------------
bool C_VS_UI_HPBAR::IsPixel(int _x, int _y)
{
	if (Moving()) return true;

	const int lx = _x - x, ly = _y - y;

	if (m_pC_hpbar_spk->IsPixel(lx, ly, MainSpriteIndex()))
		return true;

	ButtonGroup* p_group = CurrentButtonGroup();
	return p_group != NULL && p_group->IsInRect(lx, ly) != NULL;
}

//-----------------------------------------------------------------------------
// Run
//
// 
//-----------------------------------------------------------------------------
void C_VS_UI_HPBAR::Run(id_t id)
{
	switch (id)
	{
	case CHANGE_ID:
	{
		m_width_mode = !m_width_mode;

		// The old art was a straight transpose (214x37 <-> 37x214), so this used to
		// swap w/h. The renewal art is not (510x37 horizontal, 75x246 vertical), so
		// take the new size from the sprite and keep the right edge anchored, which
		// is what the swap-and-shift did for square-ish art.
		const int old_w = w;
		const int index = (m_width_mode ? MAIN_WIDTH : MAIN_HEIGHT) + m_small_offset;

		w = m_pC_hpbar_spk->GetWidth(index);
		h = m_pC_hpbar_spk->GetHeight(index);
		x += old_w - w;

		EMPTY_MOVE;
	}
	break;

	case RESIZE_ID:
		m_small_mode = !m_small_mode;
		if (m_small_mode)
		{
			switch (g_eRaceInterface)
			{
			case RACE_SLAYER:
				m_small_offset = SLAYER_MAX;
				break;

			case RACE_VAMPIRE:
				m_small_offset = VAMPIRE_MAX;
				break;

			case RACE_OUSTERS:
				m_small_offset = OUSTERS_MAX;
				break;
			}
		}
		else m_small_offset = 0;
		if (m_width_mode)
		{
			w = m_pC_hpbar_spk->GetWidth(MAIN_WIDTH + m_small_offset);
			h = m_pC_hpbar_spk->GetHeight(MAIN_WIDTH + m_small_offset);
		}
		else
		{
			w = m_pC_hpbar_spk->GetWidth(MAIN_HEIGHT + m_small_offset);
			h = m_pC_hpbar_spk->GetHeight(MAIN_HEIGHT + m_small_offset);
		}
		EMPTY_MOVE;
		break;
	}
}

//-----------------------------------------------------------------------------
// MouseControl
//
// 
//-----------------------------------------------------------------------------
bool C_VS_UI_HPBAR::MouseControl(UINT message, int _x, int _y)
{
	Window::MouseControl(message, _x, _y);
	_x -= x; _y -= y;

	// No HP/MP hover tooltip: the bar prints its own values now, and the old
	// hover regions were laid out for the pre-renewal stacked art.
	bool re = CurrentButtonGroup()->MouseControl(message, _x, _y);

	switch (message)
	{
	case M_MOVING:
		break;

	case M_LEFTBUTTON_DOWN:
	case M_LB_DOUBLECLICK:
		if (!gpC_mouse_pointer->GetPickUpItem() && re)
		{
			MoveReady();
			SetOrigin(_x, _y);
			break;
		}
		break;

	}


	return true;
}

