//-----------------------------------------------------------------------------
// MakeHPBarLevelString
//
// The centre crest shows the plain level, or the advancement title and grade
// once the character has one ("Ptah 10"). The advancement level packs both:
// tier = (level-1)/10, grade = (level-1)%10+1, the same split the item
// requirement text uses. Only the tier strings carry the title names, and they
// read "<name> grade %d or higher", so the name is their first token - which
// holds in Korean too ("??Ÿ %d??? ???").
//-----------------------------------------------------------------------------
static void MakeHPBarLevelString(char* szBuf, int nBuf)
{
	const int adv = g_char_slot_ingame.m_AdvancementLevel;

	if (adv <= 0)
	{
		sprintf_s(szBuf, nBuf, "%d", GetDisplayLevel());
		return;
	}

	const int nTiers = UI_STRING_MESSAGE_REQUIRE_ADVANCEMENT_LEVEL_10
					 - UI_STRING_MESSAGE_REQUIRE_ADVANCEMENT_LEVEL_0 + 1;
	int tier  = (adv - 1) / 10;
	int grade = (adv - 1) % 10 + 1;

	if (tier < 0)			tier = 0;
	if (tier >= nTiers)		tier = nTiers - 1;

	const char* szTier =
		(*g_pGameStringTable)[UI_STRING_MESSAGE_REQUIRE_ADVANCEMENT_LEVEL_0 + tier].GetString();

	char szName[64] = { 0, };
	int  i = 0;
	while (szTier != NULL && szTier[i] != 0 && szTier[i] != ' ' && szTier[i] != '%'
			&& i < (int)sizeof(szName) - 1)
	{
		szName[i] = szTier[i];
		++i;
	}
	szName[i] = 0;

	if (szName[0] == 0)		sprintf_s(szBuf, nBuf, "%d", grade);
	else					sprintf_s(szBuf, nBuf, "%s %d", szName, grade);
}

//-----------------------------------------------------------------------------
// C_VS_UI_HPBAR::ShowBarText
//
// Centres the three readouts over the renewal bar: HP in the left channel, the
// level (or advancement title) on the centre crest, MP/EP in the right one.
// Callers pass centre-x positions in window space; each string is centred on
// its own position and vertically centred in the channel.
//
// Text has to go through a GDI DC, so the back surface is unlocked around the
// draw and re-locked afterwards, the same way ShowButtonWidget() does it.
//-----------------------------------------------------------------------------
void C_VS_UI_HPBAR::ShowBarText(int hp_cx, int mid_cx, int right_cx, int bar_y,
								const char* szHP, const char* szMid, const char* szRight)
{
	gpC_base->m_p_DDSurface_back->Unlock();

	// 12px bold: the 10px small face was too fine to read at a glance.
	PrintInfo* pi = &gpC_base->m_user_id_pi;

	// the fill sprite is the channel, so its height is the row to centre in
	const int bar_h = m_pC_hpbar_spk->GetHeight(HPBAR_WIDTH + m_small_offset);
	const int bar_w = m_pC_hpbar_spk->GetWidth(HPBAR_WIDTH + m_small_offset);

	g_FL2_GetDC();

	// Before advancement the crest reads "Level 72" rather than a bare number
	// (an advanced character shows its title there instead). The crest is the
	// gap between the two channels; if the label would not fit inside it (the
	// small bar), the number alone stays.
	char szLevel[80];
	if (g_char_slot_ingame.m_AdvancementLevel <= 0 && szMid != NULL && szMid[0] != 0)
	{
		sprintf_s(szLevel, sizeof(szLevel), "Level %s", szMid);

		const int crest_w = (right_cx - hp_cx) - bar_w - 12;
		if (g_GetStringWidth(szLevel, pi->hfont) <= crest_w)
			szMid = szLevel;
	}

	const char* szText[3] = { szHP, szMid, szRight };
	const int   cx[3]     = { hp_cx, mid_cx, right_cx };

	for (int i = 0; i < 3; ++i)
	{
		if (szText[i] == NULL || szText[i][0] == 0)
			continue;

		int strW = g_GetStringWidth(szText[i], pi->hfont);
		int strH = g_GetStringHeight(szText[i], pi->hfont);

		g_PrintColorStrShadow(x + cx[i] - strW / 2,
								y + bar_y + (bar_h - strH) / 2,
								szText[i], *pi, RGB_WHITE, RGB_BLACK);
	}

	g_FL2_ReleaseDC();

	gpC_base->m_p_DDSurface_back->Lock();
}

//-----------------------------------------------------------------------------
// Show
//
// 
//-----------------------------------------------------------------------------
void C_VS_UI_HPBAR::Show()
{
	int hp = min(max(0, g_char_slot_ingame.HP), g_char_slot_ingame.HP_MAX);

	switch (g_eRaceInterface)
	{
	case RACE_SLAYER:
	{
		int mp = min(max(0, g_char_slot_ingame.MP), g_char_slot_ingame.MP_MAX);

		if (gpC_base->m_p_DDSurface_back->Lock())
		{
			ShowSafeZoneGlow();

			if (m_width_mode)
			{
				m_pC_hpbar_spk->BltLocked(x, y, MAIN_WIDTH + m_small_offset);
				if (m_small_mode)
					m_pC_small_width_button_group->Show();
				else
					m_pC_width_button_group->Show();

				// Renewal art: one 190x11 channel each side of the centre crest.
				//   horizontal: HP (26,19); right-hand bar x = 294 large / 209 small
				//   vertical  : HP (19,26); right-hand bar (44,26)
				int hpbar_x = 26, hpbar_y = 19, mpbar_x = 209, mpbar_y = 19;
				if (!m_small_mode)
				{
					mpbar_x = 294;
				}


				Rect rect;
				//hpbar
				rect.Set(0, 0, m_pC_hpbar_spk->GetWidth(HPBAR_WIDTH + m_small_offset) * hp / max(1, g_char_slot_ingame.HP_MAX), m_pC_hpbar_spk->GetHeight(HPBAR_WIDTH + m_small_offset));
				if (g_char_slot_ingame.bl_drained)
					m_pC_hpbar_spk->BltLockedClip(x + hpbar_x, y + hpbar_y, rect, HPBAR_BLOOD_WIDTH + m_small_offset);
				else
					m_pC_hpbar_spk->BltLockedClip(x + hpbar_x, y + hpbar_y, rect, HPBAR_WIDTH + m_small_offset);

				//mpbar
				rect.Set(0, 0, m_pC_hpbar_spk->GetWidth(MPBAR_WIDTH + m_small_offset) * mp / g_char_slot_ingame.MP_MAX, m_pC_hpbar_spk->GetHeight(MPBAR_WIDTH + m_small_offset));
				m_pC_hpbar_spk->BltLockedClip(x + mpbar_x, y + mpbar_y, rect, MPBAR_WIDTH + m_small_offset);
				// readouts: HP left, level/title on the crest, MP right
				char szHP[64], szMid[64], szRight[64];
				sprintf_s(szHP, sizeof(szHP), "%d/%d", hp, g_char_slot_ingame.HP_MAX);
				sprintf_s(szRight, sizeof(szRight), "%d/%d", mp, g_char_slot_ingame.MP_MAX);
				MakeHPBarLevelString(szMid, sizeof(szMid));
				ShowBarText(hpbar_x + m_pC_hpbar_spk->GetWidth(HPBAR_WIDTH + m_small_offset) / 2,
							m_pC_hpbar_spk->GetWidth(MAIN_WIDTH + m_small_offset) / 2,
							mpbar_x + m_pC_hpbar_spk->GetWidth(MPBAR_WIDTH + m_small_offset) / 2,
							hpbar_y, szHP, szMid, szRight);
			}
			else
			{
				m_pC_hpbar_spk->BltLocked(x, y, MAIN_HEIGHT + m_small_offset);
				if (m_small_mode)
					m_pC_small_height_button_group->Show();
				else
					m_pC_height_button_group->Show();

				// Renewal art: one 190x11 channel each side of the centre crest.
				//   horizontal: HP (26,19); right-hand bar x = 294 large / 209 small
				//   vertical  : HP (19,26); right-hand bar (44,26)
				int hpbar_x = 19, hpbar_y = 26, mpbar_x = 44, mpbar_y = 26;
				if (!m_small_mode)
				{
					// (renewal art uses the same offsets in both sizes)
				}

				Rect rect;
				//hpbar
				rect.Set(0, m_pC_hpbar_spk->GetHeight(HPBAR_HEIGHT + m_small_offset) - m_pC_hpbar_spk->GetHeight(HPBAR_HEIGHT + m_small_offset) * hp / g_char_slot_ingame.HP_MAX, m_pC_hpbar_spk->GetWidth(HPBAR_HEIGHT + m_small_offset), m_pC_hpbar_spk->GetHeight(HPBAR_HEIGHT + m_small_offset) * hp / g_char_slot_ingame.HP_MAX);
				if (g_char_slot_ingame.bl_drained)
					m_pC_hpbar_spk->BltLockedClip(x + hpbar_x, y + hpbar_y, rect, HPBAR_BLOOD_HEIGHT + m_small_offset);
				else
					m_pC_hpbar_spk->BltLockedClip(x + hpbar_x, y + hpbar_y, rect, HPBAR_HEIGHT + m_small_offset);

				//mpbar
				rect.Set(0, m_pC_hpbar_spk->GetHeight(MPBAR_HEIGHT + m_small_offset) - m_pC_hpbar_spk->GetHeight(MPBAR_HEIGHT + m_small_offset) * mp / g_char_slot_ingame.MP_MAX, m_pC_hpbar_spk->GetWidth(MPBAR_HEIGHT + m_small_offset), m_pC_hpbar_spk->GetHeight(MPBAR_HEIGHT + m_small_offset) * mp / g_char_slot_ingame.MP_MAX);
				m_pC_hpbar_spk->BltLockedClip(x + mpbar_x, y + mpbar_y, rect, MPBAR_HEIGHT + m_small_offset);
			}
			gpC_base->m_p_DDSurface_back->Unlock();
		}
		if (m_width_mode)
		{
			if (m_small_mode)
				m_pC_small_width_button_group->ShowDescription();
			else
				m_pC_width_button_group->ShowDescription();

		}
		else
		{
			if (m_small_mode)
				m_pC_small_height_button_group->ShowDescription();
			else
				m_pC_height_button_group->ShowDescription();

		}
	}
	break;

	case RACE_VAMPIRE:
	{
		if (gpC_base->m_p_DDSurface_back->Lock())
		{
			ShowSafeZoneGlow();

			if (m_width_mode)
			{
				m_pC_hpbar_spk->BltLocked(x, y, MAIN_WIDTH + m_small_offset);
				if (m_small_mode)
					m_pC_small_width_button_group->Show();
				else
					m_pC_width_button_group->Show();

				// Renewal art: one 190x11 channel each side of the centre crest.
				//   horizontal: HP (26,19); right-hand bar x = 294 large / 209 small
				//   vertical  : HP (19,26); right-hand bar (44,26)
				// Vampires have no mana, so HP is mirrored into the right channel.
				int hpbar_x = 26, hpbar_y = 19, hpbar2_x = 209;
				if (!m_small_mode)
				{
					hpbar2_x = 294;
				}

				Rect rect;

				// hpbar
				rect.Set(0, 0, m_pC_hpbar_spk->GetWidth(HPBAR_WIDTH + m_small_offset) * hp / g_char_slot_ingame.HP_MAX, m_pC_hpbar_spk->GetHeight(HPBAR_WIDTH + m_small_offset));
				m_pC_hpbar_spk->BltLockedClip(x + hpbar_x, y + hpbar_y, rect, HPBAR_WIDTH + m_small_offset);
				m_pC_hpbar_spk->BltLockedClip(x + hpbar2_x, y + hpbar_y, rect, HPBAR_WIDTH + m_small_offset);

				// slivered hpbar
				rect.Set(m_pC_hpbar_spk->GetWidth(HPBAR_SILVER_WIDTH + m_small_offset) - m_pC_hpbar_spk->GetWidth(HPBAR_SILVER_WIDTH + m_small_offset) * g_char_slot_ingame.SILVER_HP / g_char_slot_ingame.HP_MAX, 0, m_pC_hpbar_spk->GetWidth(HPBAR_SILVER_WIDTH + m_small_offset) * g_char_slot_ingame.SILVER_HP / g_char_slot_ingame.HP_MAX, m_pC_hpbar_spk->GetHeight(HPBAR_SILVER_WIDTH + m_small_offset));
				m_pC_hpbar_spk->BltLockedClip(x + hpbar_x, y + hpbar_y, rect, HPBAR_SILVER_WIDTH + m_small_offset);
				m_pC_hpbar_spk->BltLockedClip(x + hpbar2_x, y + hpbar_y, rect, HPBAR_SILVER_WIDTH + m_small_offset);
				// readouts: HP left, level/title on the crest, HP right
				char szHP[64], szMid[64], szRight[64];
				sprintf_s(szHP, sizeof(szHP), "%d/%d", hp, g_char_slot_ingame.HP_MAX);
				sprintf_s(szRight, sizeof(szRight), "%d/%d", hp, g_char_slot_ingame.HP_MAX);
				MakeHPBarLevelString(szMid, sizeof(szMid));
				ShowBarText(hpbar_x + m_pC_hpbar_spk->GetWidth(HPBAR_WIDTH + m_small_offset) / 2,
							m_pC_hpbar_spk->GetWidth(MAIN_WIDTH + m_small_offset) / 2,
							hpbar2_x + m_pC_hpbar_spk->GetWidth(HPBAR_WIDTH + m_small_offset) / 2,
							hpbar_y, szHP, szMid, szRight);

				// No exp bar: the renewal art has only two channels and HP now uses both.
			}
			else
			{
				m_pC_hpbar_spk->BltLocked(x, y, MAIN_HEIGHT + m_small_offset);
				if (m_small_mode)
					m_pC_small_height_button_group->Show();
				else
					m_pC_height_button_group->Show();

				// Renewal art: one 190x11 channel each side of the centre crest.
				//   horizontal: HP (26,19); right-hand bar x = 294 large / 209 small
				//   vertical  : HP (19,26); right-hand bar (44,26)
				// Vampires have no mana, so HP is mirrored into the right channel.
				int hpbar_x = 19, hpbar_y = 26, hpbar2_x = 44;
				if (!m_small_mode)
				{
					// (renewal art uses the same offsets in both sizes)
				}

				Rect rect;

				// hpbar
				rect.Set(0, m_pC_hpbar_spk->GetHeight(HPBAR_HEIGHT + m_small_offset) - m_pC_hpbar_spk->GetHeight(HPBAR_HEIGHT + m_small_offset) * hp / g_char_slot_ingame.HP_MAX, m_pC_hpbar_spk->GetWidth(HPBAR_HEIGHT + m_small_offset), m_pC_hpbar_spk->GetHeight(HPBAR_HEIGHT + m_small_offset) * hp / g_char_slot_ingame.HP_MAX);
				m_pC_hpbar_spk->BltLockedClip(x + hpbar_x, y + hpbar_y, rect, HPBAR_HEIGHT + m_small_offset);
				m_pC_hpbar_spk->BltLockedClip(x + hpbar2_x, y + hpbar_y, rect, HPBAR_HEIGHT + m_small_offset);

				// silver hpbar
				rect.Set(0, 0, m_pC_hpbar_spk->GetWidth(HPBAR_SILVER_HEIGHT + m_small_offset), m_pC_hpbar_spk->GetHeight(HPBAR_SILVER_HEIGHT + m_small_offset) * g_char_slot_ingame.SILVER_HP / g_char_slot_ingame.HP_MAX);
				m_pC_hpbar_spk->BltLockedClip(x + hpbar_x, y + hpbar_y, rect, HPBAR_SILVER_HEIGHT + m_small_offset);
				m_pC_hpbar_spk->BltLockedClip(x + hpbar2_x, y + hpbar_y, rect, HPBAR_SILVER_HEIGHT + m_small_offset);

				// No exp bar: the renewal art has only two channels and HP now uses both.
			}
			gpC_base->m_p_DDSurface_back->Unlock();
		}
		if (m_width_mode)
		{
			if (m_small_mode)
				m_pC_small_width_button_group->ShowDescription();
			else
				m_pC_width_button_group->ShowDescription();

		}
		else
		{
			if (m_small_mode)
				m_pC_small_height_button_group->ShowDescription();
			else
				m_pC_height_button_group->ShowDescription();
		}
	}
	break;

	case RACE_OUSTERS:
	{
		if (gpC_base->m_p_DDSurface_back->Lock())
		{
			ShowSafeZoneGlow();

			int MaxMP = max(g_char_slot_ingame.MP_MAX, 1);
			int Magnification = min(2, (g_char_slot_ingame.MP / (MaxMP + 1)));
			int CurrentMP = g_char_slot_ingame.MP - (MaxMP * Magnification);
			int mp = min(max(0, g_char_slot_ingame.MP), MaxMP);

			if (m_width_mode)
			{
				m_pC_hpbar_spk->BltLocked(x, y, MAIN_WIDTH + m_small_offset);
				if (m_small_mode)
					m_pC_small_width_button_group->Show();
				else
					m_pC_width_button_group->Show();

				//hpbar
				// Renewal art: one 190x11 channel each side of the centre crest.
				//   horizontal: HP (26,19); right-hand bar x = 294 large / 209 small
				//   vertical  : HP (19,26); right-hand bar (44,26)
				int hpbar_x = 26, hpbar_y = 19, mpbar_x = 209, mpbar_y = 19;
				if (!m_small_mode)
				{
					mpbar_x = 294;
				}

				Rect rect;

				// hpbar
				rect.Set(0, 0, m_pC_hpbar_spk->GetWidth(HPBAR_WIDTH + m_small_offset) * hp / g_char_slot_ingame.HP_MAX, m_pC_hpbar_spk->GetHeight(HPBAR_WIDTH + m_small_offset));
				//					if(g_char_slot_ingame.bl_drained)
				m_pC_hpbar_spk->BltLockedClip(x + hpbar_x, y + hpbar_y, rect, HPBAR_WIDTH + m_small_offset);
				//					else
				//						m_pC_hpbar_spk->BltLockedClip(x+hpbar_x, y+hpbar_y, rect, OUSTERS_HPBAR_BLOOD_WIDTH+m_small_offset);

									// slivered hpbar
				rect.Set(m_pC_hpbar_spk->GetWidth(OUSTERS_HPBAR_SILVER_WIDTH + m_small_offset) - m_pC_hpbar_spk->GetWidth(OUSTERS_HPBAR_SILVER_WIDTH + m_small_offset) * g_char_slot_ingame.SILVER_HP / g_char_slot_ingame.HP_MAX, 0, m_pC_hpbar_spk->GetWidth(OUSTERS_HPBAR_SILVER_WIDTH + m_small_offset) * g_char_slot_ingame.SILVER_HP / g_char_slot_ingame.HP_MAX, m_pC_hpbar_spk->GetHeight(OUSTERS_HPBAR_SILVER_WIDTH + m_small_offset));
				m_pC_hpbar_spk->BltLockedClip(x + hpbar_x, y + hpbar_y, rect, OUSTERS_HPBAR_SILVER_WIDTH + m_small_offset);

				//mpbar
				if (Magnification == 0)
				{
					rect.Set(0, 0, m_pC_hpbar_spk->GetWidth(MPBAR_WIDTH + m_small_offset) * mp / MaxMP, m_pC_hpbar_spk->GetHeight(MPBAR_WIDTH + m_small_offset));
					m_pC_hpbar_spk->BltLockedClip(x + mpbar_x, y + mpbar_y, rect, MPBAR_WIDTH + m_small_offset);
				}
				else if (Magnification == 1)
				{
					int sprIndex1 = OUSTERS_2ND_MPBAR_WIDTH + ((BYTE)m_small_mode * 4);

					rect.Set(0, 0, m_pC_hpbar_spk->GetWidth(MPBAR_WIDTH + m_small_offset), m_pC_hpbar_spk->GetHeight(MPBAR_WIDTH + m_small_offset));
					m_pC_hpbar_spk->BltLockedClip(x + mpbar_x, y + mpbar_y, rect, MPBAR_WIDTH + m_small_offset);
					rect.Set(0, 0, m_pC_hpbar_spk->GetWidth(sprIndex1) * CurrentMP / MaxMP, m_pC_hpbar_spk->GetHeight(sprIndex1));
					m_pC_hpbar_spk->BltLockedClip(x + mpbar_x, y + mpbar_y, rect, sprIndex1);
				}
				else if (Magnification == 2)
				{
					int sprIndex1 = OUSTERS_2ND_MPBAR_WIDTH + ((BYTE)m_small_mode * 4);
					int sprIndex2 = OUSTERS_3ND_MPBAR_WIDTH + ((BYTE)m_small_mode * 4);

					rect.Set(0, 0, m_pC_hpbar_spk->GetWidth(sprIndex1), m_pC_hpbar_spk->GetHeight(sprIndex1));
					m_pC_hpbar_spk->BltLockedClip(x + mpbar_x, y + mpbar_y, rect, sprIndex1);
					rect.Set(0, 0, m_pC_hpbar_spk->GetWidth(sprIndex2) * CurrentMP / MaxMP, m_pC_hpbar_spk->GetHeight(sprIndex2));
					m_pC_hpbar_spk->BltLockedClip(x + mpbar_x, y + mpbar_y, rect, sprIndex2);
				}

				// No exp bar: the renewal art has only two channels (HP and EP).
				// readouts: HP left, level/title on the crest, EP right
				char szHP[64], szMid[64], szRight[64];
				sprintf_s(szHP, sizeof(szHP), "%d/%d", hp, g_char_slot_ingame.HP_MAX);
				sprintf_s(szRight, sizeof(szRight), "%d/%d", g_char_slot_ingame.MP, g_char_slot_ingame.MP_MAX);
				MakeHPBarLevelString(szMid, sizeof(szMid));
				ShowBarText(hpbar_x + m_pC_hpbar_spk->GetWidth(HPBAR_WIDTH + m_small_offset) / 2,
							m_pC_hpbar_spk->GetWidth(MAIN_WIDTH + m_small_offset) / 2,
							mpbar_x + m_pC_hpbar_spk->GetWidth(MPBAR_WIDTH + m_small_offset) / 2,
							hpbar_y, szHP, szMid, szRight);
			}
			else
			{
				m_pC_hpbar_spk->BltLocked(x, y, MAIN_HEIGHT + m_small_offset);
				if (m_small_mode)
					m_pC_small_height_button_group->Show();
				else
					m_pC_height_button_group->Show();

				//hpbar
				// Renewal art: one 190x11 channel each side of the centre crest.
				//   horizontal: HP (26,19); right-hand bar x = 294 large / 209 small
				//   vertical  : HP (19,26); right-hand bar (44,26)
				int hpbar_x = 19, hpbar_y = 26, mpbar_x = 44, mpbar_y = 26;
				// (renewal art uses the same offsets in both sizes)

				Rect rect;

				// hpbar
				rect.Set(0, m_pC_hpbar_spk->GetHeight(HPBAR_HEIGHT + m_small_offset) - m_pC_hpbar_spk->GetHeight(HPBAR_HEIGHT + m_small_offset) * hp / g_char_slot_ingame.HP_MAX, m_pC_hpbar_spk->GetWidth(HPBAR_HEIGHT + m_small_offset), m_pC_hpbar_spk->GetHeight(HPBAR_HEIGHT + m_small_offset) * hp / g_char_slot_ingame.HP_MAX);
				m_pC_hpbar_spk->BltLockedClip(x + hpbar_x, y + hpbar_y, rect, HPBAR_HEIGHT + m_small_offset);
				//					if(g_char_slot_ingame.bl_drained)
				m_pC_hpbar_spk->BltLockedClip(x + hpbar_x, y + hpbar_y, rect, HPBAR_HEIGHT + m_small_offset);
				//					else
				//						m_pC_hpbar_spk->BltLockedClip(x+hpbar_x, y+hpbar_y, rect, OUSTERS_HPBAR_BLOOD_HEIGHT+m_small_offset);

									// slivered hpbar
				rect.Set(0, 0, m_pC_hpbar_spk->GetWidth(OUSTERS_HPBAR_SILVER_HEIGHT + m_small_offset), m_pC_hpbar_spk->GetHeight(OUSTERS_HPBAR_SILVER_HEIGHT + m_small_offset) * g_char_slot_ingame.SILVER_HP / g_char_slot_ingame.HP_MAX);
				m_pC_hpbar_spk->BltLockedClip(x + hpbar_x, y + hpbar_y, rect, OUSTERS_HPBAR_SILVER_HEIGHT + m_small_offset);

				//mpbar
				if (Magnification == 0)
				{
					rect.Set(0, m_pC_hpbar_spk->GetHeight(MPBAR_HEIGHT + m_small_offset) - m_pC_hpbar_spk->GetHeight(MPBAR_HEIGHT + m_small_offset) * mp / MaxMP, m_pC_hpbar_spk->GetWidth(MPBAR_HEIGHT + m_small_offset), m_pC_hpbar_spk->GetHeight(MPBAR_HEIGHT + m_small_offset) * mp / MaxMP);
					m_pC_hpbar_spk->BltLockedClip(x + mpbar_x, y + mpbar_y, rect, MPBAR_HEIGHT + m_small_offset);
				}
				else if (Magnification == 1)
				{
					int sprIndex1 = OUSTERS_2ND_MPBAR_HEIGHT + ((BYTE)m_small_mode * 4);

					rect.Set(0, m_pC_hpbar_spk->GetHeight(MPBAR_HEIGHT + m_small_offset) - m_pC_hpbar_spk->GetHeight(MPBAR_HEIGHT + m_small_offset),
						m_pC_hpbar_spk->GetWidth(MPBAR_HEIGHT + m_small_offset), m_pC_hpbar_spk->GetHeight(MPBAR_HEIGHT + m_small_offset));

					m_pC_hpbar_spk->BltLockedClip(x + mpbar_x, y + mpbar_y, rect, MPBAR_HEIGHT + m_small_offset);
					float mp_rate = CurrentMP / MaxMP;
					mp_rate = min(max(mp_rate, 0.0f), 1.0f);
					rect.Set(0, 0,
						//m_pC_hpbar_spk->GetHeight(sprIndex1)-m_pC_hpbar_spk->GetHeight(sprIndex1)*CurrentMP/MaxMP, 
						m_pC_hpbar_spk->GetWidth(sprIndex1), m_pC_hpbar_spk->GetHeight(sprIndex1) * mp_rate);
				}
				else if (Magnification == 2)
				{
					int sprIndex1 = OUSTERS_2ND_MPBAR_HEIGHT + ((BYTE)m_small_mode * 4);
					int sprIndex2 = OUSTERS_3ND_MPBAR_HEIGHT + ((BYTE)m_small_mode * 4);

					rect.Set(0, m_pC_hpbar_spk->GetHeight(sprIndex1) - m_pC_hpbar_spk->GetHeight(sprIndex1) * mp / MaxMP, m_pC_hpbar_spk->GetWidth(sprIndex1), m_pC_hpbar_spk->GetHeight(sprIndex1));
					m_pC_hpbar_spk->BltLockedClip(x + mpbar_x, y + mpbar_y, rect, sprIndex1);

					float mp_rate = CurrentMP / MaxMP;
					mp_rate = min(max(mp_rate, 0.0f), 1.0f);

					rect.Set(0, m_pC_hpbar_spk->GetHeight(sprIndex2) - m_pC_hpbar_spk->GetHeight(sprIndex2) * mp_rate,
						m_pC_hpbar_spk->GetWidth(sprIndex2), m_pC_hpbar_spk->GetHeight(sprIndex2) * mp_rate);
					m_pC_hpbar_spk->BltLockedClip(x + mpbar_x, y + mpbar_y, rect, sprIndex2);
				}
				// No exp bar: the renewal art has only two channels (HP and EP).
			}
			gpC_base->m_p_DDSurface_back->Unlock();
		}

		if (m_width_mode)
		{
			if (m_small_mode)
				m_pC_small_width_button_group->ShowDescription();
			else
				m_pC_width_button_group->ShowDescription();

		}
		else
		{
			if (m_small_mode)
				m_pC_small_height_button_group->ShowDescription();
			else
				m_pC_height_button_group->ShowDescription();
		}
	}
	break;
	}
}

//-----------------------------------------------------------------------------
// Start
//
// 
//-----------------------------------------------------------------------------
void C_VS_UI_HPBAR::Start()
{
	PI_Processor::Start();

	m_pC_small_width_button_group->Init();
	m_pC_small_height_button_group->Init();
	m_pC_width_button_group->Init();
	m_pC_height_button_group->Init();

	gpC_window_manager->AppearWindow(this);

	AttrAutoHide(gpC_vs_ui_window_manager->GetAutoHide(C_VS_UI_WINDOW_MANAGER::HPBAR));
	// A layout saved as vertical opens horizontal - vertical mode is gone.
	if (gpC_vs_ui_window_manager->IsHPBarSmall() != m_small_mode)Run(RESIZE_ID);

	Rect& rect = gpC_vs_ui_window_manager->GetRect(C_VS_UI_WINDOW_MANAGER::HPBAR);
	if (rect.w != -1)
	{
		x = rect.x;
		y = rect.y;
	}

}

void C_VS_UI_HPBAR::Finish()
{
	gpC_vs_ui_window_manager->SetAutoHide(C_VS_UI_WINDOW_MANAGER::HPBAR, GetAttributes()->autohide);
	gpC_vs_ui_window_manager->SetRect(C_VS_UI_WINDOW_MANAGER::HPBAR, Rect(x, y, w, h));
	gpC_vs_ui_window_manager->SetHPBarHeight(!m_width_mode);
	gpC_vs_ui_window_manager->SetHPBarSmall(m_small_mode);

	PI_Processor::Finish();

	gpC_window_manager->DisappearWindow(this);

}

//-----------------------------------------------------------------------------
// Process
//
//
//-----------------------------------------------------------------------------
void C_VS_UI_HPBAR::Process()
{
	ProcessHide();
	if (m_small_mode)
	{
		if (m_width_mode)
			m_pC_small_width_button_group->Process();
		else
			m_pC_small_height_button_group->Process();
	}
	else
	{
		if (m_width_mode)
			m_pC_width_button_group->Process();
		else
			m_pC_height_button_group->Process();
	}
}

//-----------------------------------------------------------------------------
// C_VS_UI_BLOOD_BURST
//
//-----------------------------------------------------------------------------
C_VS_UI_BLOOD_BURST::C_VS_UI_BLOOD_BURST()
{
	AttrTopmost(false);
	AttrPin(true);

	g_RegisterWindow(this);

	m_bGageAttackFull = false;
	m_bGageDefenseFull = false;
	m_bGagePartyFull = false;

	m_iAttackGage = 0;
	m_iDefenseGage = 0;
	m_iPartyGage = 0;

	// The renewal gauges: circles in a row, one pack for every race
	m_pC_BloodBurst_spk = new C_SPRITE_PACK(SPK_BLOOD_BURST_RENEWAL);

	// the shrunk set with its glow frames when the loose pack carries them
	m_glow = m_pC_BloodBurst_spk->GetSize() >= RENEWAL_GLOW_FRAME_COUNT;
	m_image_base = m_glow ? RENEWAL_SMALL_FRAME : RENEWAL_FRAME;
	m_margin = m_glow ? GLOW_MARGIN : 0;

	const int size = m_pC_BloodBurst_spk->GetWidth(m_image_base);
	const int cell = size + m_margin * 2;
	const int width = cell * GAUGE_COUNT;
	Set((g_pUserInformation->iResolution_x - width) / 2,
		g_pUserInformation->iResolution_y - s_hpbar_default_bottom - cell, width, cell);

	// one button per circle; its letter is drawn, and a click bursts, only when full
	m_pC_button_group = new ButtonGroup(this);
	static const int gauge_id[GAUGE_COUNT] = { ATTACK_ID, DEFENSE_ID, PARTY_ID };
	for (int i = 0; i < GAUGE_COUNT; ++i)
		m_pC_button_group->Add(new C_VS_UI_EVENT_BUTTON(cell * i + m_margin, m_margin, size, size, gauge_id[i], this, m_image_base + RENEWAL_LETTER_A + i));
}

C_VS_UI_BLOOD_BURST::~C_VS_UI_BLOOD_BURST()
{
	gpC_vs_ui_window_manager->SetRect(C_VS_UI_WINDOW_MANAGER::BLOOD_BURST_WINDOW, Rect(x, y, w, h));
	gpC_vs_ui_window_manager->SetBloodBurstHeight(false);
	g_UnregisterWindow(this);
	DeleteNew(m_pC_button_group);
	if (m_pC_BloodBurst_spk)
	{
		DeleteNew(m_pC_BloodBurst_spk);
		m_pC_BloodBurst_spk = NULL;
	}
}

int		C_VS_UI_BLOOD_BURST::GaugeCount() const
{
	return (g_pParty != NULL && g_pParty->GetSize() > 0) ? GAUGE_COUNT : GAUGE_COUNT - 1;
}

bool	C_VS_UI_BLOOD_BURST::IsGaugeFull(int gauge) const
{
	switch (gauge)
	{
	case 0: return m_bGageAttackFull;
	case 1: return m_bGageDefenseFull;
	case 2: return m_bGagePartyFull;
	}
	return false;
}

void	C_VS_UI_BLOOD_BURST::ShowButtonWidget(C_VS_UI_EVENT_BUTTON * p_button)
{
	// a gauge's letter shows once it is full
	const int gauge = p_button->GetID() - ATTACK_ID;
	if (gauge < 0 || gauge >= GaugeCount() || !IsGaugeFull(gauge))
		return;

	const int push = p_button->GetPressState() ? 1 : 0;
	m_pC_BloodBurst_spk->BltLocked(x + p_button->x, y + p_button->y + push, p_button->m_image_index);
}

void	C_VS_UI_BLOOD_BURST::ShowButtonDescription(C_VS_UI_EVENT_BUTTON * p_button)
{
}

void	C_VS_UI_BLOOD_BURST::WindowEventReceiver(id_t event)
{
}

bool	C_VS_UI_BLOOD_BURST::IsPixel(int _x, int _y)
{
	if (Moving()) return true;

	// only the circles on show (the party one only while in a party)
	const int cell = w / GAUGE_COUNT;
	return _x >= x && _x < x + cell * GaugeCount() && _y >= y && _y < y + h;
}

bool	C_VS_UI_BLOOD_BURST::GetOccludeRect(int* px0, int* py0, int* px1, int* py1) const
{
	*px0 = x;
	*py0 = y;
	*px1 = x + (w / GAUGE_COUNT) * GaugeCount();
	*py1 = y + h;
	return w > 0 && h > 0;
}

void	C_VS_UI_BLOOD_BURST::Run(id_t id)
{
	switch (id)
	{
	case ATTACK_ID:
		if (m_bGageAttackFull)
			gpC_base->SendMessage(UI_BLOOD_BURST, ATTACK_ID);
		break;

	case DEFENSE_ID:
		if (m_bGageDefenseFull)
			gpC_base->SendMessage(UI_BLOOD_BURST, DEFENSE_ID);
		break;

	case PARTY_ID:
		if (m_bGagePartyFull)
			gpC_base->SendMessage(UI_BLOOD_BURST, PARTY_ID);
		break;
	}
}

bool	C_VS_UI_BLOOD_BURST::MouseControl(UINT message, int _x, int _y)
{
	Window::MouseControl(message, _x, _y);
	_x -= x; _y -= y;

	// Only the round middle of a full gauge is a button. Its corners, the glow
	// margin and the gauges that are not full all drag the window.
	const int cell = w / GAUGE_COUNT;
	const int gauge = (cell > 0 && _x >= 0) ? _x / cell : -1;
	bool on_button = false;
	if (gauge >= 0 && gauge < GaugeCount() && IsGaugeFull(gauge))
	{
		const int dx = _x - (gauge * cell + cell / 2);
		const int dy = _y - h / 2;
		const int r = (cell - m_margin * 2) * 3 / 8;	// the circle inside its frame
		on_button = dx * dx + dy * dy <= r * r;
	}

	bool re = true;
	if (on_button)
		re = m_pC_button_group->MouseControl(message, _x, _y);
	else
	{
		if (message == M_LEFTBUTTON_UP)
			m_pC_button_group->CancelPushState();
		m_pC_button_group->UnacquireMouseFocus();
	}

	switch (message)
	{
	case M_MOVING:
		break;

	case M_LEFTBUTTON_DOWN:
	case M_LB_DOUBLECLICK:
		if (!gpC_mouse_pointer->GetPickUpItem() && re)
		{
			MoveReady();
			SetOrigin(_x, _y);
			break;
		}
		break;
	}
	return true;
}

void	C_VS_UI_BLOOD_BURST::KeyboardControl(UINT message, UINT key, long extra)
{
}

void	C_VS_UI_BLOOD_BURST::SetGage()
{
	SetAttackGage();
	SetDefenseGage();
	SetPartyGage();
}

void	C_VS_UI_BLOOD_BURST::SetAttackGage()
{
	m_iAttackGage = min((int)g_char_slot_ingame.AttackBloodBurstPoint, (int)ATTACK_MAX_POINT);
	m_bGageAttackFull = m_iAttackGage >= ATTACK_MAX_POINT;
}

void	C_VS_UI_BLOOD_BURST::SetDefenseGage()
{
	m_iDefenseGage = min((int)g_char_slot_ingame.DefenseBloodBurstPoint, (int)DEFENSE_MAX_POINT);
	m_bGageDefenseFull = m_iDefenseGage >= DEFENSE_MAX_POINT;
}

void	C_VS_UI_BLOOD_BURST::SetPartyGage()
{
	m_iPartyGage = min((int)g_char_slot_ingame.PartyBloodBurstPoint, (int)PARTY_MAX_POINT);
	m_bGagePartyFull = m_iPartyGage >= PARTY_MAX_POINT;
}

void	C_VS_UI_BLOOD_BURST::Show()
{
	static const int gauge_max[GAUGE_COUNT] = { ATTACK_MAX_POINT, DEFENSE_MAX_POINT, PARTY_MAX_POINT };
	const int gauge[GAUGE_COUNT] = { m_iAttackGage, m_iDefenseGage, m_iPartyGage };
	const int count = GaugeCount();
	const int cell = w / GAUGE_COUNT;

	// a full gauge breathes: a 1.2 second triangle wave drives its glow (alpha of 32)
	const DWORD phase = GetTickCount() % 1200;
	const int glow = 10 + (int)(phase < 600 ? phase : 1200 - phase) * 16 / 600;

	if (gpC_base->m_p_DDSurface_back->Lock())
	{
		for (int i = 0; i < count; ++i)
		{
			const int ox = x + cell * i;		// the cell, glow margin included
			const int cx = ox + m_margin;		// the frame and circle
			const int cy = y + m_margin;
			const int circle = m_image_base + RENEWAL_ATTACK + i;
			const int cw = m_pC_BloodBurst_spk->GetWidth(circle);
			const int ch = m_pC_BloodBurst_spk->GetHeight(circle);
			const bool lit = m_glow && IsGaugeFull(i);

			// halo behind a full circle: a wide faint disc, then a tighter brighter one
			if (lit)
			{
				m_pC_BloodBurst_spk->BltLockedAlpha(ox, y, RENEWAL_HALO_OUTER_ATTACK + i, glow / 2);
				m_pC_BloodBurst_spk->BltLockedAlpha(ox + 2, y + 2, RENEWAL_HALO_MID_ATTACK + i, glow);
			}

			// the empty circle dimmed, then the filled part rising from the bottom
			m_pC_BloodBurst_spk->BltLockedDarkness(cx, cy, circle, 2);
			const int fill = min(ch, ch * gauge[i] / gauge_max[i]);
			if (fill > 0)
			{
				Rect rect(0, ch - fill, cw, fill);
				m_pC_BloodBurst_spk->BltLockedClip(cx, cy, rect, circle);
			}

			// and the full circle itself brightens with the same breath
			if (lit)
				m_pC_BloodBurst_spk->BltLockedAlpha(cx, cy, RENEWAL_LIT_ATTACK + i, glow);

			m_pC_BloodBurst_spk->BltLocked(cx, cy, m_image_base + RENEWAL_FRAME);
		}

		m_pC_button_group->Show();
		gpC_base->m_p_DDSurface_back->Unlock();
	}
	// "rampage n / max" while the pointer is over a circle
	const int print_x = gpC_mouse_pointer->GetPointerX();
	const int print_y = gpC_mouse_pointer->GetPointerY();
	if (cell > 0 && print_y >= y && print_y < y + h && print_x >= x && print_x < x + cell * count)
	{
		static const int tip[GAUGE_COUNT] = { UI_STRING_MESSAGE_BLOOD_BURST_ATTACK, UI_STRING_MESSAGE_BLOOD_BURST_DEFENSE, UI_STRING_MESSAGE_BLOOD_BURST_PARTY };
		static std::string bloodburst_string;
		// DID_HELP reads an S_DEFAULT_HELP_STRING: main, main2, sub - all three must be valid or NULL
		const static char* help_string[3] = { NULL, NULL, NULL };

		const int i = (print_x - x) / cell;
		char temp_string[512];
		wsprintf(temp_string, (*g_pGameStringTable)[tip[i]].GetString(), gauge[i], gauge_max[i]);
		bloodburst_string = temp_string;

		help_string[0] = bloodburst_string.c_str();
		g_descriptor_manager.Set(DID_HELP, print_x + 30, print_y, (void*)help_string, 0, 0);
	}
}

void	C_VS_UI_BLOOD_BURST::Process()
{
	ProcessHide();
	m_pC_button_group->Process();
}

void	C_VS_UI_BLOOD_BURST::Start()
{
	// a position saved in the old vertical layout can sit off the left or top edge
	Rect& rect = gpC_vs_ui_window_manager->GetRect(C_VS_UI_WINDOW_MANAGER::BLOOD_BURST_WINDOW);
	if (rect.w != -1)
	{
		x = max(0, (int)rect.x);
		y = max(0, (int)rect.y);
	}

	PI_Processor::Start();
	SetGage();
	m_pC_button_group->Init();
	gpC_window_manager->AppearWindow(this);
}

void	C_VS_UI_BLOOD_BURST::Finish()
{
	gpC_vs_ui_window_manager->SetRect(C_VS_UI_WINDOW_MANAGER::BLOOD_BURST_WINDOW, Rect(x, y, w, h));
	gpC_vs_ui_window_manager->SetBloodBurstHeight(false);
	PI_Processor::Finish();

	gpC_window_manager->DisappearWindow(this);
}



