//
// 
//-----------------------------------------------------------------------------
bool C_VS_UI_MINIMAP::IsPixel(int _x, int _y)
{
	// 2006.08.22 sjheon
	if (m_bMiniMapDisableZone)
		return false;

	if (Moving())
		return true;

	return IsInRect(_x, _y) ? true : false;
}

