void C_VS_UI_WINDOW_MANAGER::SetSMSMynum(char* str)
{
	int len = strlen(str);
	if (len > 0 && len < 12)
	{
		strcpy(m_SMS_MyNum, str);
		m_SMS_MyNum[len] = '\0';
	}
}


