void	C_VS_UI_BRING_FEE::KeyboardControl(UINT message, UINT key, long extra)

{
	Window::KeyboardControl(message, key, extra);

	if (message == WM_KEYDOWN)
	{
		switch (key)
		{
		case VK_ESCAPE:
			gpC_base->SendMessage(UI_CLOSE_BRING_FEE_WINDOW);
			break;
		}
	}
}

